window.PORTAL={"day": 16, "title": "Cardiology + Days 13–15 System Revision", "docTitle": "NEET-SS + ICP PAEDIATRICS", "subtitle": ["Consolidated Study Pack | Days 13–16", "Part I: Completed-system revision — Days 13–15. Part II: Day 16 Cardiology study edition. Cardiology system-end revision remains scheduled for Day 21."], "source": "source/NEET_SS_ICP_Consolidated_Days13-16_Reviewed.docx", "pages": [{"id": "overview", "title": "Overview", "group": "Start", "kind": "overview", "sections": [{"title": "", "blocks": [{"t": "p", "html": "Consolidated Study Pack | Days 13–16"}, {"t": "p", "html": "Part I: Completed-system revision — Days 13–15. Part II: Day 16 Cardiology study edition. Cardiology system-end revision remains scheduled for Day 21."}]}, {"title": "Comparison and Editorial Decision", "h1": "Comparison and Editorial Decision", "blocks": [{"t": "p", "html": "The Days 13–15 document is a system-end rapid-revision, traps and volatile-facts resource; the Day 16 document is a daily teaching and assessment resource. They are complementary, not competing revisions of the same content."}, {"t": "p", "html": "Both original documents are preserved in their original sequence below, including tables, diagrams and answer sections. Content has not been medically rewritten or independently validated in this consolidation."}, {"t": "p", "html": "QA limitation: This consolidation is a structural comparison and preservation exercise. It does not certify that every clinical dose, threshold, guideline attribution, or answer key has been independently verified. Refer to source registers and local protocols for clinical decisions."}, {"t": "p", "html": "PART I — COMPLETED SYSTEM: DAYS 13–15"}, {"t": "p", "html": "SYSTEM-END REVISION"}, {"t": "p", "html": "Growth • Development • Nutrition • Genetics / Inborn Errors of Metabolism"}, {"t": "p", "html": "Days 13–15  |  11–13 October 2026  |  A4 monochrome learner edition"}, {"t": "callout", "label": "", "title": "", "html": ["THE THREE-PART REVISION PATH", "• PART 1 — Complete Rapid Revision Note: mechanisms, diagnostics, treatment, algorithms, numbers, 35 pearls and last-minute checklist.", "• PART 2 — SYSTEM TRAP NOTE: 40 factual, close-distractor traps with seven repeated fields and day/source trace-back.", "• PART 3 — Volatile Facts Deck: one-look cutoffs, timing, syndrome/biochemistry clues, formulas, RED/AMBER/GREEN and final 5-minute recall.", "TRACE / SOURCE: Locked 73-day curriculum; Day 13–15 final study editions"], "fill": "E8E8E8"}, {"t": "callout", "label": "", "title": "", "html": ["PROTOCOL RULE FOR THIS DOCUMENT", "• Nelson Textbook of Pediatrics 22e is the primary conceptual framework; OP Ghai complements Indian clinical context. Cloherty &amp; Stark is a neonatal specialty reference, not a source of invented page-level claims.", "• IAP Practice Guidelines 2026 and Indian NHM/MoHFW programme documents lead when they address the question. WHO and ACMG recommendations are named separately.", "• Numbers used in programme-based questions depend on age band, preparation and exact guideline. Unverified protocol-specific doses are not presented as universal treatment orders.", "• Only Day 13–15 curriculum content is included; previous-system concepts are included only where the Day 15 IEM overlap and actual notebook justify them.", "TRACE / SOURCE: IAP Action Plan 2026; NHM 2025/2026; WHO 2023/2026"], "fill": "F5F5F5"}, {"t": "callout", "label": "", "title": "", "html": ["PERSONAL NOTEBOOK STATUS AT GENERATION", "• The available NEET_SS_Error_Notebook.md contains no user-reported errors explicitly from Days 13, 14 or 15 as of the source snapshot.", "• One genuine cross-day overlap: Day 10 Q65 (OTC vs CPS1/NAGS), R1 passed 12 October; it is retained as AMBER/Improving for Day 15 IEM. Day 10 Q50 (hyperinsulinism biochemical discriminator) is a secondary IEM differential, not a new Day 15 error.", "• Do not infer guessed-correct items, R1/R2/R3 success or repeated x2/x3 failures for this system when not documented.", "TRACE / SOURCE: Actual persistent notebook, version 22, materialized 13 October 2026"], "fill": "F8F8F8"}]}, {"title": "Learning Objectives", "h1": "Learning Objectives", "blocks": [{"t": "list", "ordered": false, "items": ["Explain fetal streaming through ductus venosus, foramen ovale and ductus arteriosus and the PVR/SVR transition after birth.", "Classify neonatal cyanosis, shock, differential saturation and duct-dependent pulmonary/systemic circulation.", "Apply IAP-NNF Presidential Action Plan 2026 CCHD screening criteria without using superseded pass/retest rules.", "Distinguish innocent from pathological murmurs using timing, location, intensity, radiation, posture and associated signs.", "Interpret paediatric ECG using age-dependent rate, axis, intervals, T waves and ventricular-dominance patterns.", "Read paediatric CXR systematically: projection, cardiothoracic silhouette, pulmonary vascularity and classic pattern limitations.", "Choose echocardiography and urgent stabilization appropriately when screening, ECG or CXR appears reassuring.", "Retest documented earlier weak areas without counting them among the 75 new cardiology MCQs."]}]}, {"title": "Objective → Case → Assessment Traceability", "h1": "Objective → Case → Assessment Traceability", "blocks": [{"t": "table", "head": ["<strong>Mapped subtopic</strong>", "<strong>Teaching / case / station</strong>", "<strong>Base MCQs</strong>"], "rows": [["Fetal shunts and transition", "A1–A3; cases 1–3; station 1", "Q1–12, Q14–15, Q25, Q75"], ["CCHD screening and emergency approach", "A4–A6; cases 2, 3, 6; stations 2, 6", "Q16–24, Q26–30, Q74, Q78–80"], ["Murmurs and auscultation", "A7; cases 4, 5; station 3", "Q32–46, Q73, Q76"], ["Age-specific ECG", "A8; case 7; station 4", "Q47–48, Q50–63"], ["Chest radiography", "A9; case 8; station 5", "Q64, Q66–72"], ["Error notebook", "5 separate retests; notebook reconciliation appendix", "5 retests (Q13, Q31, Q49, Q65, Q77); outside the 75 base"]]}]}]}, {"id": "part-1", "title": "Complete Rapid Revision Note", "eyebrow": "", "group": "Days 13–15 Revision", "kind": "notes", "sections": [{"title": "1. System map and day traceability", "blocks": [{"t": "table", "head": ["<strong>Day</strong>", "<strong>Mapped curriculum</strong>", "<strong>Revision sections</strong>"], "rows": [["13", "WHO/IAP growth charts; short stature; growth faltering; developmental milestones, GDD/regression; ASD/ADHD/SLD/language/sleep red flags", "§2–6; §15; §17"], ["14", "Breastfeeding, complementary feeding, nutrition assessment, MAM/SAM, vitamin A/D/B12, iron/zinc/iodine, Indian prevention programmes", "§7–10; §15–17"], ["15", "Chromosomal syndromes, dysmorphology, genetic testing, inheritance/imprinting, IEM recognition/emergencies, newborn screening", "§11–14; §15–17"]]}]}, {"title": "2. Growth: WHAT → WHY → HOW → RECOGNIZE → WHAT NEXT", "blocks": [{"t": "callout", "label": "", "title": "", "html": ["GROWTH DECISION CHAIN", "• WHAT: growth is a trajectory, not a single percentile. WHY: nutrition affects weight first; endocrine and skeletal disorders may primarily affect height.", "• HOW: verify technique/age, select chart, plot serial measurements, calculate height velocity and genetic target, assess body proportions and puberty.", "• RECOGNIZE: crossing ≥2 major centile lines, height &lt;−2 SDS, poor velocity, disproportion, unexplained edema/weight loss, height far from mid-parental target.", "• WHAT NEXT: nutrition/feeding assessment for weight-first faltering; targeted screening for systemic disease; bone age and endocrine referral if height-first pattern; genetics/skeletal evaluation for dysmorphism or disproportion.", "TRACE / SOURCE: Day 13 &gt; Growth Charts / IAP Growth Charts 2026"], "fill": "F5F5F5"}, {"t": "table", "head": ["<strong>Age / setting</strong>", "<strong>Reference</strong>", "<strong>Decisive exam distinction</strong>"], "rows": [["Birth to 5 y", "WHO 2006 growth standards", "Z scores for WAZ, HAZ, WHZ, BMI-for-age; WHO is prescriptive."], ["5–18 y India", "IAP 2015 Indian reference", "BMI adult-equivalent 23 and 27 lines for overweight/obesity."], ["Preterm infant", "Corrected-age-appropriate preterm chart per follow-up programme", "Do not plot chronological age without correcting when required; IAP 2026 cites INTERGROWTH-21st."], ["Known syndrome", "Syndrome-specific charts plus population charts", "Syndrome-specific trend does not replace general nutritional evaluation."]]}, {"t": "table", "head": ["<strong>Growth indicator</strong>", "<strong>What it detects</strong>", "<strong>What it cannot establish</strong>"], "rows": [["WAZ", "Underweight", "Acute vs chronic mechanism alone"], ["HAZ / LAZ", "Stunting, linear-growth impairment", "Specific endocrine diagnosis"], ["WHZ / WLZ", "Wasting / acute malnutrition", "Long-term linear deficit"], ["MUAC 6–59 mo", "Acute malnutrition / mortality risk", "Not the same as height-for-age"], ["BMI-for-age", "Thinness or excess adiposity", "Cannot substitute for body composition"]]}, {"t": "callout", "label": "", "title": "", "html": ["MUST-KNOW GROWTH NUMBERS", "• Short stature: height &lt;−2 SDS (about 3rd centile); severe &lt;−3 SDS merits prompt evaluation.", "• IAP 2026 rough linear growth velocity: 0–1 y ≈25 cm/y; 1–2 y ≈12 cm/y; 2–4 y ≈7–8 cm/y; 4 y–puberty ≈5–6 cm/y.", "• Mid-parental height: boy (father + mother + 13 cm)/2; girl (father + mother −13 cm)/2; IAP 2026 target band about ±6 cm.", "• Height velocity (cm/year) = (height2 − height1) ×12 / elapsed months; use standardized serial measurements, usually ≥6 months apart.", "TRACE / SOURCE: Day 13 &gt; Must-Know Numbers; IAP 2026 Growth Charts"], "fill": "F5F5F5"}]}, {"title": "3. Short stature and growth faltering — discriminate before tests", "blocks": [{"t": "table", "head": ["<strong>Pattern</strong>", "<strong>Favors</strong>", "<strong>Decisive clue / first work-up</strong>"], "rows": [["Low weight precedes reduced height", "Inadequate intake, malabsorption, chronic inflammation", "Detailed feeding, stool/illness history, serial weights; investigate selectively."], ["Height slows while weight preserved/increased", "Endocrine cause", "Bone age; TSH/FT4, IGF-1 axis as clinically indicated; refer."], ["Normal velocity + short parents", "Familial short stature", "Bone age often ≈ chronological age; within genetic target."], ["Late puberty + delayed bone age", "Constitutional delay", "Family history of late maturation; normal/near-normal interval velocity."], ["Disproportion or skeletal deformity", "Skeletal dysplasia / rickets", "Upper/lower ratio, arm span, targeted skeletal evaluation."], ["Short girl + Turner clues", "Turner syndrome", "Karyotype even if phenotype is subtle."], ["Persistent SGA without catch-up", "SGA-related short stature", "Review age, growth trend, systemic causes; endocrine referral after expected catch-up period."]]}, {"t": "callout", "label": "", "title": "", "html": ["ALGORITHM 1 — Short stature", "• 1. Confirm accurate stadiometry and age/sex chart; calculate height SDS.", "• 2. Review ≥6–12-month growth velocity and parental target height.", "• 3. Classify weight-first, height-first, proportionate or disproportionate pattern.", "• 4. Look for red flags: puberty abnormality, dysmorphism, chronic disease, neurologic or skeletal features.", "• 5. Order targeted CBC, ESR/CRP, thyroid tests, renal/liver tests, celiac serology + total IgA, bone age or genetic tests when indicated.", "• 6. Treat the cause, refer to endocrine/genetics when indicated, and repeat standardized measures.", "TRACE / SOURCE: Day 13 &gt; Short Stature / IAP 2026"], "fill": "F7F7F7"}, {"t": "callout", "label": "", "title": "", "html": ["ALGORITHM 2 — Growth faltering / poor weight gain", "• 1. Validate weight/length, growth chart and prior trajectory.", "• 2. Take detailed milk transfer, food frequency, texture, feeding interaction, illness and psychosocial history.", "• 3. Assess hydration, edema, micronutrient signs, swallowing/aspiration and chronic disease red flags.", "• 4. Determine whether acute malnutrition criteria or serious illness require urgent referral.", "• 5. Implement nutrition/lactation plan and targeted testing; monitor serial weight gain and developmental progress.", "TRACE / SOURCE: Day 13 &gt; Growth Faltering; Day 14 &gt; Feeding"], "fill": "F7F7F7"}]}, {"title": "4. Developmental milestones, delay and regression", "blocks": [{"t": "table", "head": ["<strong>Age</strong>", "<strong>Gross motor</strong>", "<strong>Fine motor / social / language (approximate IAP 2026 anchors)</strong>"], "rows": [["6 wk–2 mo", "Lifts chin briefly", "Social smile ~6 wk; early vocalization"], ["3–4 mo", "Head control developing", "Reaches, coos, tracks"], ["6 mo", "Rolls; sits with support", "Transfers hand-to-hand; monosyllabic babble"], ["9 mo", "Sits unsupported; pulls to stand", "Immature pincer; gestures/stranger anxiety; bisyllabic babble"], ["12–15 mo", "Cruises / walks with support then independent", "Mature pincer; first meaningful words; points/shows"], ["18 mo", "Walks confidently, stairs with hand held", "Spoon use; imitation; meaningful words; check for regression"], ["2 y", "Runs, stairs two-feet-per-step", "Two-word combinations; 6-block tower (teaching anchor)"], ["3 y", "Tricycle/jumps", "Copies circle; pretend play; conversational speech"], ["4–5 y", "Hops at 4; skips at 5", "Copies cross ~4; triangle ~5; cooperative play"]]}, {"t": "callout", "label": "", "title": "", "html": ["DEVELOPMENTAL RED FLAGS / NEXT ACTION", "• Any loss of previously acquired words, social skills or motor skills = regression → urgent assessment; do not reassure based on prior normal milestones.", "• Not sitting unsupported around 9 months, not walking independently by 18 months, absent meaningful words/joint attention or no pretend play at expected age warrants formal assessment.", "• Isolated expressive language delay requires hearing evaluation; receptive/social-communication deficits suggest broader neurodevelopmental concern.", "• Global developmental delay (GDD): significant delay in at least two developmental domains, generally in children &lt;5 years; diagnosis requires standardized assessment.", "• Preterm correction: corrected age = chronological age − (40 − GA at birth); distinguish PMA = GA at birth + chronological age.", "TRACE / SOURCE: Day 13 &gt; Development; IAP 2026 Milestones"], "fill": "F5F5F5"}, {"t": "callout", "label": "", "title": "", "html": ["ALGORITHM 3 — Child with developmental delay / regression", "• 1. Identify delay vs plateau vs true loss of skills; screen for acute red flags and seizures.", "• 2. Check hearing and vision, preterm correction, family/pregnancy history, and domain-specific exam.", "• 3. Use validated developmental tools and neurological examination; refer early intervention now, not after diagnostic certainty.", "• 4. If dysmorphic, multisystem or unexplained GDD: clinical genetics and phenotype-directed CMA / exome-genome strategy.", "• 5. If regression, episodic decompensation or organomegaly: metabolic/neurodegenerative differential and targeted urgent tests.", "TRACE / SOURCE: Day 13 &gt; Development; Day 15 &gt; Genetics"], "fill": "F7F7F7"}]}, {"title": "5. ASD, ADHD, specific learning disorder and language/sleep overlays", "blocks": [{"t": "table", "head": ["<strong>Entity</strong>", "<strong>Core discriminator</strong>", "<strong>First action / common trap</strong>"], "rows": [["ASD", "Social-communication deficits AND restricted/repetitive patterns; joint-attention/gesture deficits", "M-CHAT-R/F is screening, not diagnosis; refer for comprehensive assessment."], ["Isolated language delay", "Language affected, but reciprocal social interest/gestures relatively preserved", "Audiology and speech-language assessment; assess receptive language."], ["ADHD", "Developmentally inappropriate inattention and/or hyperactivity/impulsivity across ≥2 settings with impairment", "Rule out sleep loss, hearing/vision, anxiety, learning disorder; single-parent rating is insufficient."], ["Specific learning disorder", "Persistent domain-specific reading/writing/math difficulty despite appropriate opportunity/intervention", "Assess schooling, language, vision/hearing and cognitive context; not equivalent to low IQ."], ["Sleep-disordered breathing", "Snoring with witnessed apnea, gasping, daytime behavioral issues", "Sleep assessment/OSA referral; do not automatically label ADHD."], ["Developmental regression", "Loss of skills, not mere slow acquisition", "Urgent neurology/metabolic evaluation; avoid watchful waiting."]]}, {"t": "callout", "label": "", "title": "", "html": ["LATEST PROTOCOL UPDATE | ASD screening age is framework-specific", "• IAP 2026 emphasizes proactive identification and M-CHAT-R/F screening in toddlers aged 16–30 months with clinical assessment.", "• AAP/CDC (2026 description) recommends general developmental screening at 9, 18, 30 months and ASD-specific screening at 18 and 24 months. A positive screen is not a diagnosis.", "TRACE / SOURCE: IAP Neurodevelopment 2026 / CDC 2026"], "fill": "EBEBEB"}]}, {"title": "6. Growth/development imaging and data clues", "blocks": [{"t": "p", "html": "• Growth curve: declining weight SDS with initially stable height → nutritional faltering; falling height velocity with preserved weight → endocrine suspicion. Trace: D13 &gt; Growth."}, {"t": "p", "html": "• Bone-age film: delayed BA with delayed puberty suggests constitutional delay but is not specific; BA ≈ chronological age with short parents suggests familial short stature. Trace: D13 &gt; Short Stature."}, {"t": "p", "html": "• Head circumference curve: rapid upward crossing or progressive microcephaly demands neurological assessment; consider craniosynostosis, hydrocephalus, genetics. Trace: D13 &gt; Growth."}, {"t": "p", "html": "• General-movements video / HINE / MRI: abnormal early motor trajectory in high-risk infant supports early CP evaluation, not waiting for spasticity. Trace: D13 &gt; High-risk Follow-up."}, {"t": "p", "html": "• No pointing to share interest plus stereotyped play is more discriminating for ASD than vocabulary count alone. Trace: D13 &gt; ASD."}]}, {"title": "7. Nutrition: WHAT → WHY → HOW → RECOGNIZE → WHAT NEXT", "blocks": [{"t": "callout", "label": "", "title": "", "html": ["FEEDING CHAIN", "• WHAT: inadequate energy, protein or micronutrients impair growth and neurodevelopment; repeated infection increases demand and worsens absorption.", "• WHY: milk-transfer problems, inappropriate complementary-food density, restricted diet, chronic disease or poverty can drive growth faltering.", "• HOW: observe a complete breastfeed; quantify age-appropriate meal frequency, texture, diversity, appetite and illness.", "• RECOGNIZE: poor weight trajectory, edema, MUAC/WHZ thresholds, anemia, rickets, xerophthalmia, neurologic B12 signs.", "• WHAT NEXT: urgent SAM triage when indicated; skilled lactation/nutrition support; Indian supplementation programme where applicable; evaluate red flags.", "TRACE / SOURCE: Day 14 &gt; Feeding/Nutrition"], "fill": "F5F5F5"}, {"t": "table", "head": ["<strong>Feeding stage</strong>", "<strong>Guideline anchor</strong>", "<strong>Pitfall</strong>"], "rows": [["Birth", "Initiate breastfeeding within first hour if clinically feasible", "Colostrum is not to be discarded."], ["0–6 completed months", "Exclusive breastfeeding (no routine water/other feeds)", "Assess transfer and growth, not just reported feed frequency."], ["At 6 completed months", "Start safe, thick, diverse complementary foods while continuing breastfeeding", "Dilute watery gruels have low energy density."], ["6–8 months", "Typically 2–3 meals/day", "Progress texture, not only volume."], ["9–23 months", "Typically 3–4 meals/day plus 1–2 snacks as needed", "Responsive feeding; do not force or use screens."], ["Up to 2 y or beyond", "Continue breastfeeding", "Complementary food must meet rising iron/zinc/energy needs."]]}, {"t": "callout", "label": "", "title": "", "html": ["LATEST PROTOCOL UPDATE | Complementary feeding 2023 / infant feeding 2026", "• WHO 2023 guideline covers 6–23 months and emphasizes diverse nutrient-dense foods, responsive feeding and context-specific recommendations.", "• WHO infant and young child feeding fact sheet updated 4 August 2026 retains breastfeeding within 1 hour, exclusive 6 months, and complementary foods at 6 months with breastfeeding to ≥2 years.", "• IAP 2026 infant-nutrition chapter is the default Indian clinical framing.", "TRACE / SOURCE: WHO 2023 / WHO 4 Aug 2026 / IAP Nutrition 2026"], "fill": "EBEBEB"}]}, {"title": "8. MAM/SAM — classification, emergency sequence and disposition", "blocks": [{"t": "table", "head": ["<strong>Age 6–59 mo</strong>", "<strong>Definition (WHO / IAP 2026)</strong>", "<strong>Disposition</strong>"], "rows": [["SAM", "WHZ &lt;−3 OR MUAC &lt;11.5 cm OR bilateral nutritional pitting edema", "Medical complication, poor appetite or unstable child → facility/NRC; otherwise community pathway per programme."], ["MAM", "WHZ ≥−3 and &lt;−2 OR MUAC ≥11.5 and &lt;12.5 cm, no edema", "Community nutrition support with medical evaluation and follow-up."], ["Stunting", "HAZ &lt;−2; severe &lt;−3", "Chronic linear-growth indicator, not interchangeable with SAM."], ["Underweight", "WAZ &lt;−2", "Does not distinguish acute from chronic causes."]]}, {"t": "callout", "label": "", "title": "", "html": ["ALGORITHM 4 — Acute malnutrition triage (6–59 months)", "• 1. Measure MUAC and WHZ; examine both feet for nutritional pitting edema.", "• 2. If any SAM criterion present, label SAM even if other measures look normal.", "• 3. Assess appetite and danger signs: hypoglycemia, hypothermia, shock, severe infection, dehydration, anemia, altered sensorium.", "• 4. Complicated SAM or failed appetite test → urgent facility-based stabilization; uncomplicated with good appetite → supervised community care.", "• 5. During inpatient stabilization: prevent/treat hypoglycemia and hypothermia, assess infection and dehydration cautiously, correct electrolytes, start appropriate starter feeding.", "• 6. After clinical stabilization/appetite return/edema improves: transition to catch-up feeding (F-100 or approved RUTF protocol), then rehabilitation and close relapse surveillance.", "TRACE / SOURCE: Day 14 &gt; SAM / IAP 2026 / WHO 2023 &amp; 2026"], "fill": "F7F7F7"}, {"t": "callout", "label": "", "title": "", "html": ["SAM TREATMENT DISCRIMINATORS", "• F-75 ≈75 kcal/100 mL: low-protein/low-sodium starter diet for stabilization; F-100 ≈100 kcal/100 mL: rehabilitation/catch-up phase, not initial feeding in unstable SAM.", "• Rehydration in SAM is cautious; dehydration signs can be unreliable and fluid overload is hazardous. Use current programme-specific rehydration pathway.", "• Iron is generally deferred during initial unstable stabilization and added during rehabilitation once appetite and infection status improve, per protocol.", "• Do not assume every SAM child requires admission; appetite/medical complications decide setting.", "• WHO implementation guidance published 17 September 2026 updates operational interpretation of WHO 2023 recommendations; national adoption and product rules remain country-specific.", "TRACE / SOURCE: Day 14 &gt; SAM; IAP 2026; WHO 2026 Implementation"], "fill": "F5F5F5"}]}, {"title": "9. Vitamins/minerals: recognize pattern, test and act", "blocks": [{"t": "table", "head": ["<strong>Deficiency</strong>", "<strong>Classic recognition</strong>", "<strong>Testing / treatment principle</strong>"], "rows": [["Vitamin A", "Night blindness, Bitot spots, xerophthalmia, keratomalacia", "Urgent ocular care + therapeutic vitamin A under age-specific protocol; do not confuse with prophylaxis."], ["Vitamin D / calcium", "Widened wrists, rachitic rosary, bowing, hypocalcemic seizures; high ALP", "25-OH D, calcium, phosphate, PTH, ALP; treat calcium intake and vitamin D; distinguish phosphopenic rickets."], ["Vitamin B12", "Macrocytosis, hypotonia, regression, developmental delay; maternal vegan/restricted diet", "B12, CBC, MMA/homocysteine where available; neurologic treatment should not await all tests."], ["Iron", "Microcytosis, pallor, pica, poor intake; low ferritin if not inflamed", "Elemental iron dosing depends on treatment vs prophylaxis; evaluate thalassemia if indices discordant."], ["Zinc", "Poor growth, dermatitis, alopecia, diarrhea; acrodermatitis enteropathica", "Replace zinc; NHM diarrhea programme uses age-specific 14-day course."], ["Iodine", "Goiter, hypothyroidism, developmental impairment", "Iodized salt; thyroid function and neonatal screening; avoid indiscriminate iodine dosing."], ["Vitamin C", "Pseudoparalysis, bleeding gums, subperiosteal hemorrhage, scorbutic rosary", "Diet history + radiograph; treat vitamin C."], ["Vitamin K", "Bleeding tendency, prolonged PT/INR", "Differentiate deficiency from hepatic disease; age-appropriate prophylaxis at birth."]]}, {"t": "callout", "label": "", "title": "", "html": ["LATEST PROTOCOL UPDATE | Indian vitamin A prophylaxis (NHM updated 7 Aug 2026)", "• Dose 1: 100,000 IU at 9 months (with measles-containing vaccination).", "• Doses 2–9: 200,000 IU at 16–18 months and every 6 months thereafter until 5 years (9 total doses).", "• This is prevention; xerophthalmia treatment uses a separate age-specific high-dose schedule.", "TRACE / SOURCE: NHM Vitamin A page updated 7 Aug 2026; NHM IMNCI 2023"], "fill": "EBEBEB"}, {"t": "callout", "label": "", "title": "", "html": ["LATEST PROTOCOL UPDATE | Zinc for childhood diarrhea (NHM STOP Diarrhoea 2025)", "• Age &lt;2 months: programme does not recommend routine zinc under this campaign.", "• 2 to &lt;6 months: 10 mg elemental zinc daily for 14 days; ≥6 months to 5 years: 20 mg daily for 14 days.", "• Give ORS/appropriate rehydration as the core diarrhea treatment; zinc is an adjunct.", "TRACE / SOURCE: NHM STOP Diarrhoea Campaign Guidance 2025"], "fill": "EBEBEB"}, {"t": "callout", "label": "", "title": "", "html": ["IRON / VITAMIN D — PREVENTION IS NOT TREATMENT", "• Anemia Mukt Bharat: children 6–59 months receive IFA syrup twice weekly (formulation/programme-specific); therapeutic iron for iron-deficiency anemia is a separate mg/kg/day elemental-iron prescription.", "• Common therapeutic oral elemental iron for pediatric IDA is about 3 mg/kg/day (some protocols 3–6 mg/kg/day); calculate elemental, not salt mass; review adherence, response and underlying cause.", "• Routine vitamin D infant supplementation often uses 400 IU/day in common pediatric guidance; nutritional rickets treatment uses substantially higher supervised regimens plus calcium and follow-up, not a single universal stoss dose.", "TRACE / SOURCE: NHM Anemia Mukt Bharat; WHO vitamin D/rickets guidance"], "fill": "F5F5F5"}]}, {"title": "10. Nutrition management calculations and data interpretation", "blocks": [{"t": "table", "head": ["<strong>Formula</strong>", "<strong>Worked example / caution</strong>"], "rows": [["BMI = weight (kg) / height (m)^2", "20 kg at 1.10 m → 20/1.21 = 16.53 kg/m²; interpret on age/sex chart."], ["WHZ, HAZ, WAZ", "Use WHO LMS calculator/chart; (value − median)/SD is only a rough conceptual shortcut."], ["Elemental iron (mg/day) = mg/kg/day × weight", "3 mg/kg/day × 12 kg = 36 mg elemental/day; salt content differs by preparation."], ["Feed volume (mL) = target kcal / formula kcal per mL", "F-75 0.75 kcal/mL: 600 kcal ≈800 mL; this is arithmetic, NOT a bedside SAM starting order."], ["Vitamin A volume = IU needed / IU per mL", "100,000 IU / 100,000 IU/mL = 1 mL; confirm actual bottle concentration."], ["Annualized height velocity", "4 cm in 8 months → 4 ×12/8 = 6 cm/year."]]}]}, {"title": "11. Genetics and dysmorphology: mechanism → test → next step", "blocks": [{"t": "callout", "label": "", "title": "", "html": ["GENETIC REASONING CHAIN", "• WHAT: chromosome dosage, copy number, sequence variants, repeats, imprinting, mitochondrial inheritance and multifactorial traits create recognizable phenotypes.", "• WHY: the assay must match variant class; a normal karyotype cannot rule out a microdeletion or monogenic disorder.", "• HOW: three-generation pedigree + pregnancy/birth history + growth, HC, proportions, major/minor anomalies and targeted organ screening.", "• RECOGNIZE: aneuploid phenotype, syndrome-specific facial/cardiac pattern, hypotonia/hyperphagia, congenital anomalies, regression or biochemical decompensation.", "• WHAT NEXT: choose karyotype/CMA/methylation/repeat assay/exome-genome/biochemical testing; begin phenotype-directed surveillance and counselling.", "TRACE / SOURCE: Day 15 &gt; Genetics / IAP Genetics 2026"], "fill": "F5F5F5"}, {"t": "table", "head": ["<strong>Test</strong>", "<strong>Detects best</strong>", "<strong>Major blind spot / pitfall</strong>"], "rows": [["Karyotype", "Aneuploidy, large rearrangements, balanced translocations", "Small CNVs and single-nucleotide variants."], ["CMA / SNP array", "Genome-wide deletions/duplications, some UPD/isodisomy patterns", "Balanced rearrangements; small sequence variants; methylation status."], ["FISH / MLPA", "Targeted known deletion/duplication", "Not genome-wide in typical use."], ["Methylation 15q11-q13", "Imprinting signature of PWS/AS", "Some Angelman UBE3A sequence variants have normal methylation."], ["Exome/genome", "Coding / broader sequence variants; genome may capture more structural/intronic variants", "A negative result does not exclude all repeat, methylation, mosaic or mtDNA defects."], ["Repeat-expansion test", "FMR1, Huntington, myotonic dystrophy, etc.", "Conventional exome may miss repeat expansions."], ["Biochemical metabolomics", "Amino acids, acylcarnitines, urine organic acids, ammonia", "Screening biomarkers are not definitive genotypes."]]}, {"t": "callout", "label": "", "title": "", "html": ["LATEST PROTOCOL UPDATE | ACMG 2021 + IAP 2026 genomic-test selection", "• ACMG 2021 strongly recommends considering exome/genome sequencing as first- or second-tier for congenital anomalies, developmental delay or intellectual disability.", "• IAP 2026 emphasizes phenotype-directed testing: CMA for suspected CNV; exome for heterogeneous monogenic conditions; targeted assay for known syndrome or repeat.", "• Do not use the outdated absolute rule “CMA must always precede exome”.", "TRACE / SOURCE: ACMG 2021 Genetics in Medicine; IAP 2026 Advanced Genomic Testing"], "fill": "EBEBEB"}, {"t": "callout", "label": "", "title": "", "html": ["DYSMORPHOLOGY CLASSIFICATION — DO NOT CONFUSE TERMS", "• Major anomaly: structural abnormality with substantial medical/functional or cosmetic impact; minor anomaly: limited clinical impact but may be a syndromic clue when multiple are present.", "• Malformation: intrinsic abnormal morphogenesis (e.g. cleft lip); deformation: extrinsic mechanical molding (e.g. positional clubfoot); disruption: breakdown of previously normal tissue (e.g. amniotic band); dysplasia: disordered tissue organization (e.g. skeletal dysplasia).", "• Sequence: one initiating defect leads to downstream anomalies (Pierre Robin sequence: micrognathia → glossoptosis → cleft palate/airway issues).", "• Association: nonrandom co-occurrence without one established unifying etiology (VACTERL); syndrome: recognizable pattern with a common cause or mechanism.", "TRACE / SOURCE: Day 15 &gt; Dysmorphology / IAP Evaluation of a Dysmorphic Child 2026"], "fill": "F5F5F5"}]}, {"title": "12. Syndromes and inheritance — close discriminator table", "blocks": [{"t": "table", "head": ["<strong>Syndrome</strong>", "<strong>Genetic mechanism</strong>", "<strong>Clue and critical screening</strong>"], "rows": [["Down", "Trisomy 21, translocation or mosaicism", "Hypotonia, single palmar crease, AVSD; thyroid/hearing/vision/OSA and hematology surveillance."], ["Turner", "45,X or mosaic / structural X", "Short stature, webbed neck, left-sided cardiac/renal anomalies; karyotype; monitor aorta/hearing/thyroid."], ["Klinefelter", "47,XXY", "Tall adolescent, small firm testes, hypergonadotropic hypogonadism, learning/language issues."], ["22q11.2 deletion", "Microdeletion", "Conotruncal anomaly, hypocalcemia, palatal defect, T-cell deficiency; immune evaluation before live vaccines."], ["Williams", "7q11.23 deletion incl. ELN", "Supravalvular aortic stenosis, hypercalcemia tendency, sociable phenotype; CMA."], ["Prader–Willi", "Loss of paternal expression 15q11-q13", "Neonatal hypotonia/poor feeding → childhood hyperphagia; methylation testing."], ["Angelman", "Loss of maternal neuronal UBE3A", "Severe speech impairment, ataxia, seizures, frequent laughter; methylation/UBE3A testing."], ["Fragile X", "FMR1 CGG repeat expansion", "Long face, large ears, macroorchidism after puberty, ASD/GDD; targeted repeat assay."], ["Trisomy 18", "Extra chromosome 18", "Overlapping clenched fingers, rocker-bottom feet, severe growth restriction."], ["Trisomy 13", "Extra chromosome 13", "Holoprosencephaly, polydactyly, cleft, scalp defects."]]}, {"t": "callout", "label": "", "title": "", "html": ["INHERITANCE / COUNSELLING FACTS", "• Autosomal recessive carrier × carrier: each pregnancy 25% affected, 50% carrier, 25% unaffected noncarrier.", "• Autosomal dominant heterozygote × unaffected: 50% transmission if penetrance not considered.", "• X-linked recessive carrier mother: 50% of sons affected; 50% of daughters carriers (simplified, unaffected father).", "• Mitochondrial mtDNA variants are maternally transmitted; heteroplasmy creates variable severity.", "• PWS: loss of paternally expressed genes; Angelman: loss of maternal neuronal UBE3A; methylation detects most imprinting mechanisms.", "TRACE / SOURCE: Day 15 &gt; Inheritance/Imprinting; NHS Genomics Knowledge Hub"], "fill": "F5F5F5"}]}, {"title": "13. IEM emergency: pattern → mechanism → action", "blocks": [{"t": "table", "head": ["<strong>Biochemical phenotype</strong>", "<strong>Think first</strong>", "<strong>Diagnostic discriminator</strong>"], "rows": [["Hyperammonemia + respiratory alkalosis, often no marked acidosis", "Urea cycle defect", "Plasma amino acids, citrulline, urine orotic acid."], ["High anion-gap metabolic acidosis + ketosis ± hyperammonemia", "Organic acidemia (PA/MMA etc.)", "Urine organic acids, acylcarnitine C3, B12 status."], ["Hypoketotic hypoglycemia + high FFA", "Fatty-acid oxidation defect", "Acylcarnitine pattern, e.g. C8 in MCAD."], ["Hypoketotic hypoglycemia + suppressed FFA", "Hyperinsulinism", "Critical sample and glucagon response; distinct from FAOD."], ["Lactic acidosis + multisystem / neurologic findings", "Mitochondrial / pyruvate metabolism", "Lactate-pyruvate context, MRI, gene testing; lactate can be normal intermittently."], ["Organomegaly + coarse facies + regression", "Lysosomal storage disorder", "Enzyme testing, urine GAGs / specific metabolites, genetics."], ["Hypotonia + leukodystrophy + VLCFA elevation", "Peroxisomal disorder", "VLCFA panel and targeted genetics."]]}, {"t": "callout", "label": "", "title": "", "html": ["ALGORITHM 5 — Suspected IEM decompensation", "• 1. Stabilize ABC, shock and seizures; evaluate/treat sepsis in parallel.", "• 2. Stop catabolic stress: halt offending protein/long-chain fat intake briefly according to suspected disorder; start adequate IV glucose and specialist-directed lipids.", "• 3. Before treatment if immediately feasible: blood gas, glucose, electrolytes/anion gap, lactate, ammonia (proper sample handling), ketones, LFT, CBC, blood culture, plasma amino acids/acylcarnitines and urine organic acids.", "• 4. Classify dominant pattern: hyperammonemia/respiratory alkalosis, ketotic acidosis, hypoketotic hypoglycemia or lactic/multisystem.", "• 5. Consult metabolic ICU early; use nitrogen scavengers/arginine or other cofactors only per confirmed/suspected defect and local specialist protocol.", "• 6. If severe or rising ammonia, arrange urgent extracorporeal clearance; do not wait for molecular diagnosis.", "• 7. Reintroduce appropriate nutrition early after stabilization under metabolic supervision and plan family counselling.", "TRACE / SOURCE: Day 15 &gt; Sick Neonate/IEM; CHOP pathway; PCRRT consensus"], "fill": "F7F7F7"}, {"t": "callout", "label": "", "title": "", "html": ["LATEST PROTOCOL UPDATE | Hyperammonemia escalation — do NOT blend thresholds", "• CHOP institutional neonatal pathway: mild &lt;200 µmol/L without encephalopathy; moderate 200–500; severe ≥500 or severe encephalopathy/respiratory alkalosis. It uses a high anti-catabolic GIR (10–15 mg/kg/min) in selected neonatal pathways.", "• PCRRT 2020 expert consensus: ammonia &gt;500 µmol/L is a published dialysis indication; 301–499 with moderate/severe encephalopathy should trigger scavengers and dialysis preparation. Another 2022 consensus favors lower dialysis thresholds in young children; these are not identical rules.", "• Emergency action is based on neurologic status, ammonia trajectory and specialist protocol, not a single memorized threshold. Scavenger infusion doses require pharmacy/metabolic team verification.", "TRACE / SOURCE: CHOP Neonatal Hyperammonemia pathway; PCRRT 2020; 2022 consensus"], "fill": "EBEBEB"}, {"t": "table", "head": ["<strong>Urea cycle defect</strong>", "<strong>Citrulline / other marker</strong>", "<strong>Orotic acid / clue</strong>"], "rows": [["NAGS or CPS1", "Very low citrulline", "Normal/low orotic acid; NAGS may respond to carglumic acid."], ["OTC", "Low citrulline", "High urinary orotic acid (carbamoyl phosphate overflow)."], ["ASS1 (citrullinemia I)", "Markedly high citrulline", "Argininosuccinate absent/low; can cause neonatal crisis."], ["ASL deficiency", "Elevated citrulline + argininosuccinate", "Argininosuccinic acid detectable; brittle hair/trichorrhexis nodosa."], ["ARG1 deficiency", "Elevated arginine", "Spasticity often later; arginine therapy is not routine in ARG1 deficiency."]]}, {"t": "callout", "label": "", "title": "", "html": ["IEM MUST-RECOGNIZE TREATABLE CLUES", "• PKU: high phenylalanine; dietary phenylalanine restriction with tyrosine adequacy; screen-positive must be confirmed.", "• Classic galactosemia: jaundice/hepatopathy, E. coli sepsis, cataracts after milk feeds; immediately remove galactose/lactose pending evaluation.", "• MSUD: maple-syrup odor, neonatal encephalopathy, elevated branched-chain amino acids / alloisoleucine; metabolic crisis treatment urgent.", "• Homocystinuria (CBS): downward lens dislocation + thrombosis + marfanoid habitus; pyridoxine responsiveness varies.", "• MCAD: fasting-induced hypoketotic hypoglycemia + C8 elevation; avoid fasting and give prompt dextrose during illness.", "• MMA vs PA: both may elevate C3; MMA and methylmalonate differ from PA; check B12/cobalamin defects and maternal B12 deficiency.", "• Pompe: infant cardiomyopathy/hypotonia; Gaucher: hepatosplenomegaly, cytopenias; MPS: coarse facies, organomegaly, dysostosis.", "• X-linked adrenoleukodystrophy: VLCFA elevation; Zellweger spectrum: hypotonia, seizures, dysmorphism, VLCFA elevation.", "TRACE / SOURCE: Day 15 &gt; IEM pattern recognition"], "fill": "F5F5F5"}]}, {"title": "14. Newborn screening: screening ≠ diagnosis", "blocks": [{"t": "callout", "label": "", "title": "", "html": ["ALGORITHM 6 — Positive newborn screen", "• 1. Identify exact analyte, specimen age, gestation, transfusion/TPN context and programme cutoffs.", "• 2. Contact family and metabolic/endocrine service promptly; assess whether child is symptomatic.", "• 3. If unwell, stabilize and treat immediately; do not wait for confirmatory result.", "• 4. Order condition-specific confirmatory plasma/urine enzyme or molecular testing.", "• 5. Explain false positives, false negatives and programme-panel variability; arrange follow-up and family testing.", "TRACE / SOURCE: Day 15 &gt; Newborn Screening"], "fill": "F7F7F7"}, {"t": "callout", "label": "", "title": "", "html": ["SCREENING LIMITATIONS", "• India does not have a single universal expanded newborn screening panel covering every state and facility; local programme rules vary.", "• Tandem MS detects characteristic metabolites, not the causal genotype. Elevated C3 is not diagnostic of propionic acidemia alone.", "• A normal newborn screen does not rule out a metabolic disorder in a sick child; symptoms always override screening reassurance.", "• Congenital hypothyroidism screening and treatment are programme-/assay-specific; obtain confirmatory venous TSH and free T4 and treat promptly when indicated, without delaying for imaging.", "TRACE / SOURCE: Day 15 &gt; Newborn Screening / ISPAE/Indian programme context"], "fill": "F5F5F5"}]}, {"title": "15. Integrated comparisons: initial vs definitive, stabilize first", "blocks": [{"t": "table", "head": ["<strong>Clinical question</strong>", "<strong>Initial / stabilize first</strong>", "<strong>Definitive / later</strong>"], "rows": [["Short stature", "Serial measures, velocity, body proportions, growth chart", "Targeted endocrine/genetic evaluation by phenotype"], ["Language delay", "Audiology + developmental surveillance", "Multidisciplinary speech/developmental diagnosis"], ["ASD suspicion", "Clinical assessment and validated screen", "Comprehensive DSM-5-based evaluation; screen ≠ diagnosis"], ["Complicated SAM", "Hypoglycemia/hypothermia/infection and careful fluids, F-75", "Transition/rehabilitation with F-100 or RUTF per programme"], ["Night blindness with corneal involvement", "Protect cornea + urgent vitamin A therapy", "Etiologic nutrition care and visual follow-up"], ["Genetic syndrome with suspected CNV", "Phenotype/organ screen + CMA", "Molecular mechanism, counselling, family testing"], ["Neonatal hyperammonemia", "ABCs + anti-catabolic calories + urgent metabolic advice", "Biochemical/genetic confirmation after emergency therapy"], ["Positive NBS", "Contact/reassess, confirm biochemically", "Enzyme/molecular confirmation and long-term care"]]}]}, {"title": "16. Must-Know Numbers, doses, timings — consolidated", "blocks": [{"t": "table", "head": ["<strong>Number / dose / window</strong>", "<strong>Correct interpretation and source</strong>"], "rows": [["0–5 y WHO; 5–18 y IAP", "IAP 2026 growth reference choice"], ["Height &lt;−2 SDS", "Short stature; assess trajectory, velocity, target height"], ["MPH ±6 cm", "IAP 2026 target-height range (approximate)"], ["Velocity 25 / 12 / 7–8 / 5–6 cm/y", "IAP 2026 ages 0–1 / 1–2 / 2–4 / 4–puberty"], ["Corrected age = PNA − (40−GA)", "Preterm age correction, units must match"], ["M-CHAT-R/F 16–30 mo", "IAP 2026 toddler screening age range"], ["ASD screens 18, 24 mo", "AAP/CDC international schedule, not an Indian mandate"], ["SAM: WHZ &lt;−3 / MUAC &lt;11.5 / edema", "6–59 mo criteria, any one sufficient"], ["MAM: WHZ −3 to &lt;−2 / MUAC 11.5–&lt;12.5", "6–59 mo, no nutritional edema"], ["F-75 0.75; F-100 1.00 kcal/mL", "Stabilization vs rehabilitation; not a universal feed order"], ["Vitamin A 100,000 IU at 9 mo", "NHM India 2026 prophylaxis dose 1"], ["Vitamin A 200,000 IU 16–18 mo onward", "NHM doses 2–9 at 6-month intervals to 5 y"], ["Zinc 10 mg 2–&lt;6 mo; 20 mg ≥6 mo", "NHM STOP Diarrhoea 2025, 14 days"], ["Iron ~3 mg/kg/day elemental", "Common IDA treatment anchor; distinguish prophylaxis and protocol-specific range"], ["Ammonia ≥500 µmol/L", "CHOP severe category; PCRRT dialysis planning threshold, not universal sole criterion"], ["AR 25% affected per pregnancy", "Two heterozygous carriers, simplified Mendelian assumption"], ["AD 50% transmission", "Heterozygote parent, simplified assumption"]]}]}, {"title": "17. Thirty-five ultra-high-yield exam pearls", "blocks": [{"t": "p", "html": "• 1. Choose the correct chart before interpreting any percentile. [D13 &gt; Charts]"}, {"t": "p", "html": "• 2. Height velocity and target height matter more than a single height point. [D13 &gt; Growth]"}, {"t": "p", "html": "• 3. WHO 0–5 y; IAP 2015 reference 5–18 y in India. [D13 &gt; Charts]"}, {"t": "p", "html": "• 4. Indian IAP BMI cutoffs use adult-equivalent 23 and 27 curves. [D13 &gt; Charts]"}, {"t": "p", "html": "• 5. Weight-first faltering points to nutrition/systemic illness; height-first with preserved weight suggests endocrine cause. [D13 &gt; Patterns]"}, {"t": "p", "html": "• 6. Familial short stature: normal velocity, BA ≈ chronological age, short family. [D13 &gt; Short Stature]"}, {"t": "p", "html": "• 7. Constitutional delay: delayed puberty and bone age, often familial late maturation. [D13 &gt; Short Stature]"}, {"t": "p", "html": "• 8. Disproportion demands skeletal/genetic assessment before labeling GH deficiency. [D13 &gt; Short Stature]"}, {"t": "p", "html": "• 9. Regression of any acquired developmental skill is an urgent red flag. [D13 &gt; Development]"}, {"t": "p", "html": "• 10. GDD involves at least two affected developmental domains in young children. [D13 &gt; Development]"}, {"t": "p", "html": "• 11. Preterm corrected age and PMA are not interchangeable. [D13 &gt; Corrected Age]"}, {"t": "p", "html": "• 12. ASD requires both social-communication and restricted/repetitive domains. [D13 &gt; ASD]"}, {"t": "p", "html": "• 13. M-CHAT-R/F is a screen; diagnosis is clinical/multidisciplinary. [D13 &gt; ASD]"}, {"t": "p", "html": "• 14. Poor gestures/joint attention favors ASD over isolated expressive delay. [D13 &gt; ASD]"}, {"t": "p", "html": "• 15. Sleep apnea can masquerade as inattention/behavioral difficulty. [D13 &gt; Sleep]"}, {"t": "p", "html": "• 16. Breastfeeding: first hour, exclusive six months, continue to two years or beyond. [D14 &gt; BF]"}, {"t": "p", "html": "• 17. Complementary food at six months must be thick, diverse and energy dense. [D14 &gt; CF]"}, {"t": "p", "html": "• 18. Responsive feeding is not coercion or screen distraction. [D14 &gt; CF]"}, {"t": "p", "html": "• 19. Any one SAM criterion is sufficient, including bilateral pitting edema. [D14 &gt; SAM]"}, {"t": "p", "html": "• 20. Complicated SAM or poor appetite → facility; uncomplicated with appetite → community care. [D14 &gt; SAM]"}, {"t": "p", "html": "• 21. F-75 stabilizes; F-100/RUTF rehabilitates. [D14 &gt; SAM]"}, {"t": "p", "html": "• 22. Dehydration assessment in SAM is unreliable; avoid reflexive rapid fluid loading. [D14 &gt; SAM]"}, {"t": "p", "html": "• 23. Vitamin A prophylaxis and xerophthalmia treatment use different schedules. [D14 &gt; Vitamin A]"}, {"t": "p", "html": "• 24. India vitamin A: 100,000 IU at 9 mo, then 200,000 IU 8 more doses. [D14 &gt; NHM]"}, {"t": "p", "html": "• 25. India diarrhea zinc: 10 mg at 2–&lt;6 mo; 20 mg ≥6 mo for 14 days. [D14 &gt; NHM]"}, {"t": "p", "html": "• 26. Elemental iron dose is not equal to ferrous salt mass. [D14 &gt; Iron]"}, {"t": "p", "html": "• 27. Low ferritin suggests iron deficiency; inflammation can elevate ferritin. [D14 &gt; Iron]"}, {"t": "p", "html": "• 28. Genetic test must match variant class: balanced rearrangement ≠ CNV ≠ SNV. [D15 &gt; Tests]"}, {"t": "p", "html": "• 29. ACMG 2021 supports exome/genome first- or second-tier for CA/DD/ID. [D15 &gt; Genomics]"}, {"t": "p", "html": "• 30. PWS loses paternal expression; Angelman loses maternal neuronal UBE3A. [D15 &gt; Imprinting]"}, {"t": "p", "html": "• 31. Conotruncal defect + hypocalcemia + palatal anomaly → 22q11.2 deletion. [D15 &gt; Syndromes]"}, {"t": "p", "html": "• 32. Hyperammonemia + respiratory alkalosis suggests UCD; ketotic acidosis suggests organic acidemia. [D15 &gt; IEM]"}, {"t": "p", "html": "• 33. OTC: low citrulline + HIGH urine orotic acid; CPS1/NAGS: low/normal orotic acid. [D15 &gt; UCD; Notebook D10 Q65]"}, {"t": "p", "html": "• 34. Hypoketotic hypoglycemia with high FFA → FAOD; low FFA → hyperinsulinism. [D15 &gt; IEM]"}, {"t": "p", "html": "• 35. Newborn screening is not diagnosis; symptoms override a negative screen. [D15 &gt; NBS]"}]}, {"title": "18. Last 5–10 minute Part 1 checklist", "blocks": [{"t": "p", "html": "□ Chart ages, growth velocity, MPH, weight-first vs height-first pattern."}, {"t": "p", "html": "□ Developmental red flags, corrected age, ASD/ADHD/SLD vs language delay."}, {"t": "p", "html": "□ Breastfeeding/complementary feeding and responsive feeding ages."}, {"t": "p", "html": "□ SAM vs MAM criteria, F-75 vs F-100, complicated SAM disposition."}, {"t": "p", "html": "□ Vitamin A, zinc and iron preventive vs therapeutic schedules."}, {"t": "p", "html": "□ CMA vs exome vs karyotype vs methylation/repeat testing."}, {"t": "p", "html": "□ Down/Turner/Klinefelter/22q11/Williams/PWS/Angelman clues."}, {"t": "p", "html": "□ IEM acid-base/ketone/ammonia discriminator and urgent sequence."}, {"t": "p", "html": "□ OTC vs CPS1/NAGS vs ASS1 vs ASL; FAOD vs hyperinsulinism."}, {"t": "p", "html": "□ Newborn screening positive ≠ diagnosis; cross-day notebook Q65."}]}]}, {"id": "part-2", "title": "System Trap Note — Growth, Development, Nutrition, Genetics/IEM", "eyebrow": "", "group": "Days 13–15 Revision", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "p", "html": "RED concepts first, then AMBER/Improving, then common system-wide traps. No Day 13–15 personal errors were present in the retrieved notebook; the only personalized IEM overlap is Day 10 Q65 (R1 passed)."}, {"t": "callout", "label": "", "title": "", "html": ["Trap 1 — AMBER — OTC vs CPS1/NAGS", "<strong>Tempting wrong choice: </strong>Low citrulline alone proves CPS1 deficiency.", "<strong>Why it looks right: </strong>Both proximal UCDs and OTC can have low citrulline.", "<strong>Decisive discriminator: </strong>Urinary orotic acid HIGH in OTC, low/normal in CPS1/NAGS.", "<strong>Correct rule: </strong>Interpret citrulline + orotic acid together.", "<strong>Latest protocol: </strong>Biochemical UCD pathway; PCRRT 2020 emergency framework", "<strong>What to do in the exam: </strong>Choose OTC if low citrulline + high orotic acid.", "<strong>Trace-back: </strong>Notebook &gt; Day10 Q65 (R1 passed 12 Oct) / Day15 &gt; UCD"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 2 — AMBER — FAOD vs hyperinsulinism", "<strong>Tempting wrong choice: </strong>All hypoketotic hypoglycemia is FAOD.", "<strong>Why it looks right: </strong>Both suppress ketogenesis.", "<strong>Decisive discriminator: </strong>FFA often high in FAOD but suppressed in hyperinsulinism.", "<strong>Correct rule: </strong>Use critical-sample ketones + FFA + acylcarnitines.", "<strong>Latest protocol: </strong>Metabolic diagnostic framework; Day15 IEM", "<strong>What to do in the exam: </strong>Look at FFA before deciding.", "<strong>Trace-back: </strong>Notebook &gt; Day10 Q50 (cross-day; R1 passed) / Day15 &gt; IEM"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 3 — Wrong chart at age six", "<strong>Tempting wrong choice: </strong>Use WHO 0–5 charts for a 7-year-old Indian child.", "<strong>Why it looks right: </strong>WHO standards are widely used.", "<strong>Decisive discriminator: </strong>IAP 2015 reference applies at 5–18 y in India.", "<strong>Correct rule: </strong>WHO 0–5; IAP 5–18.", "<strong>Latest protocol: </strong>IAP Growth Charts 2026", "<strong>What to do in the exam: </strong>Identify exact age and country before interpreting.", "<strong>Trace-back: </strong>Day13 &gt; Growth Charts"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 4 — Single height centile", "<strong>Tempting wrong choice: </strong>A height at 4th centile rules out pathology.", "<strong>Why it looks right: </strong>It is just above common −2 SDS cutoff.", "<strong>Decisive discriminator: </strong>Velocity and parental target may be abnormal.", "<strong>Correct rule: </strong>Interpret longitudinal trajectory and MPH.", "<strong>Latest protocol: </strong>IAP Growth Charts 2026", "<strong>What to do in the exam: </strong>Calculate velocity and compare target.", "<strong>Trace-back: </strong>Day13 &gt; Growth"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 5 — IAP BMI 23 vs 25", "<strong>Tempting wrong choice: </strong>Use adult BMI 25/30 equivalents in Indian schoolchildren.", "<strong>Why it looks right: </strong>International adult cutoffs are familiar.", "<strong>Decisive discriminator: </strong>IAP curves use 23/27 adult-equivalent cutoffs.", "<strong>Correct rule: </strong>Use 23 overweight, 27 obesity on IAP charts.", "<strong>Latest protocol: </strong>IAP Growth Charts 2026", "<strong>What to do in the exam: </strong>Named Indian framework wins.", "<strong>Trace-back: </strong>Day13 &gt; BMI"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 6 — Growth velocity short interval", "<strong>Tempting wrong choice: </strong>Annualize two heights taken 3 weeks apart.", "<strong>Why it looks right: </strong>Mathematically possible.", "<strong>Decisive discriminator: </strong>Measurement error overwhelms short interval.", "<strong>Correct rule: </strong>Prefer standardized 6–12-month serial measures.", "<strong>Latest protocol: </strong>IAP Short Stature 2026", "<strong>What to do in the exam: </strong>Do not overinterpret noise.", "<strong>Trace-back: </strong>Day13 &gt; Growth Velocity"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 7 — Weight-first vs height-first", "<strong>Tempting wrong choice: </strong>Endocrine GH deficiency is the first cause when weight falls before height.", "<strong>Why it looks right: </strong>Growth failure sounds endocrine.", "<strong>Decisive discriminator: </strong>Undernutrition commonly affects weight first.", "<strong>Correct rule: </strong>Assess nutrition/systemic illness first.", "<strong>Latest protocol: </strong>IAP Growth Faltering 2026", "<strong>What to do in the exam: </strong>Read trajectory order.", "<strong>Trace-back: </strong>Day13 &gt; Faltering"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 8 — Familial vs constitutional", "<strong>Tempting wrong choice: </strong>Delayed bone age is typical of familial short stature.", "<strong>Why it looks right: </strong>Both are normal variants.", "<strong>Decisive discriminator: </strong>FSS BA ≈ chronological; constitutional delay BA delayed.", "<strong>Correct rule: </strong>Use BA + family puberty history + velocity.", "<strong>Latest protocol: </strong>IAP Short Stature 2026", "<strong>What to do in the exam: </strong>Differentiate with bone age.", "<strong>Trace-back: </strong>Day13 &gt; Short Stature"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 9 — Disproportion and GH", "<strong>Tempting wrong choice: </strong>Treat short limbs with GH before skeletal exam.", "<strong>Why it looks right: </strong>Short stature prompts endocrine referral.", "<strong>Decisive discriminator: </strong>Disproportion suggests skeletal dysplasia.", "<strong>Correct rule: </strong>Assess proportions, skeletal/genetic phenotype first.", "<strong>Latest protocol: </strong>IAP Short Stature 2026", "<strong>What to do in the exam: </strong>Examine arm span and US/LS ratio.", "<strong>Trace-back: </strong>Day13 &gt; Skeletal Pattern"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 10 — Short girl without stigmata", "<strong>Tempting wrong choice: </strong>No webbed neck excludes Turner syndrome.", "<strong>Why it looks right: </strong>Classic appearance is memorable.", "<strong>Decisive discriminator: </strong>Mosaic/variable phenotype may be subtle.", "<strong>Correct rule: </strong>Consider karyotype in unexplained short stature in girls.", "<strong>Latest protocol: </strong>IAP Short Stature 2026 / Genetics 2026", "<strong>What to do in the exam: </strong>Do not require every classic sign.", "<strong>Trace-back: </strong>Day13 &gt; Turner"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 11 — Celiac with IgA deficiency", "<strong>Tempting wrong choice: </strong>Negative tTG-IgA excludes celiac in IgA deficiency.", "<strong>Why it looks right: </strong>tTG-IgA is usually first-line.", "<strong>Decisive discriminator: </strong>IgA deficiency invalidates IgA-only screening.", "<strong>Correct rule: </strong>Check total IgA; use IgG-based tests when IgA deficient.", "<strong>Latest protocol: </strong>Standard celiac diagnostic principle", "<strong>What to do in the exam: </strong>Look for false-negative mechanism.", "<strong>Trace-back: </strong>Day13 &gt; Faltering"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 12 — PMA vs corrected age", "<strong>Tempting wrong choice: </strong>PMA of 43 weeks means corrected age 43 weeks.", "<strong>Why it looks right: </strong>Both are age measures.", "<strong>Decisive discriminator: </strong>PMA = GA + PNA; corrected age = PNA − (40−GA).", "<strong>Correct rule: </strong>Calculate each separately.", "<strong>Latest protocol: </strong>IAP developmental follow-up", "<strong>What to do in the exam: </strong>Write formula first.", "<strong>Trace-back: </strong>Day13 &gt; Preterm Correction"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 13 — Regression = delay", "<strong>Tempting wrong choice: </strong>Loss of words is merely delayed speech.", "<strong>Why it looks right: </strong>Child previously had language issues.", "<strong>Decisive discriminator: </strong>True loss of acquired skills is regression.", "<strong>Correct rule: </strong>Urgent evaluation; do not wait and watch.", "<strong>Latest protocol: </strong>IAP Milestones 2026", "<strong>What to do in the exam: </strong>Spot direction of change.", "<strong>Trace-back: </strong>Day13 &gt; Regression"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 14 — ASD vs language delay", "<strong>Tempting wrong choice: </strong>Normal vocabulary count excludes ASD.", "<strong>Why it looks right: </strong>Language seems preserved.", "<strong>Decisive discriminator: </strong>Absent pointing/joint attention and repetitive behaviors carry more weight.", "<strong>Correct rule: </strong>ASD requires both core domains, regardless of vocabulary count.", "<strong>Latest protocol: </strong>IAP Autism Recognition 2026", "<strong>What to do in the exam: </strong>Use gestures and reciprocity.", "<strong>Trace-back: </strong>Day13 &gt; ASD"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 15 — M-CHAT as diagnosis", "<strong>Tempting wrong choice: </strong>Positive M-CHAT-R/F establishes ASD.", "<strong>Why it looks right: </strong>Screen has validated sensitivity.", "<strong>Decisive discriminator: </strong>Screening ≠ DSM-5 diagnosis.", "<strong>Correct rule: </strong>Refer for comprehensive assessment and early support.", "<strong>Latest protocol: </strong>IAP Autism 2026 / CDC 2026", "<strong>What to do in the exam: </strong>Use “screen positive” wording.", "<strong>Trace-back: </strong>Day13 &gt; ASD"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 16 — AAP screening ages mixed with IAP", "<strong>Tempting wrong choice: </strong>M-CHAT only at 18 and 24 months in every setting.", "<strong>Why it looks right: </strong>AAP schedule is common.", "<strong>Decisive discriminator: </strong>IAP tool age range 16–30 months; AAP schedule 18/24 months.", "<strong>Correct rule: </strong>Label guideline and screening purpose.", "<strong>Latest protocol: </strong>IAP 2026 vs AAP/CDC 2026", "<strong>What to do in the exam: </strong>Named framework decides.", "<strong>Trace-back: </strong>Day13 &gt; ASD Screening"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 17 — ADHD one setting", "<strong>Tempting wrong choice: </strong>Hyperactivity reported by one teacher proves ADHD.", "<strong>Why it looks right: </strong>School reports may be convincing.", "<strong>Decisive discriminator: </strong>Impairment and symptoms in ≥2 settings needed.", "<strong>Correct rule: </strong>Gather multiple informants and rule out sleep/learning disorders.", "<strong>Latest protocol: </strong>IAP ADHD 2026 / DSM-5", "<strong>What to do in the exam: </strong>Check settings and impairment.", "<strong>Trace-back: </strong>Day13 &gt; ADHD"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 18 — OSA as ADHD", "<strong>Tempting wrong choice: </strong>Snoring with inattention is primary ADHD until proven otherwise.", "<strong>Why it looks right: </strong>Behavior resembles ADHD.", "<strong>Decisive discriminator: </strong>Sleep-disordered breathing can cause daytime symptoms.", "<strong>Correct rule: </strong>Investigate snoring/apnea and sleep quality.", "<strong>Latest protocol: </strong>IAP Sleep/ADHD 2026", "<strong>What to do in the exam: </strong>Check sleep history.", "<strong>Trace-back: </strong>Day13 &gt; Sleep"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 19 — Exclusive BF vs complementary", "<strong>Tempting wrong choice: </strong>Water or thin gruel at 4 months is harmless routine complement.", "<strong>Why it looks right: </strong>Infant appears hungry.", "<strong>Decisive discriminator: </strong>Exclusive BF is recommended first 6 months.", "<strong>Correct rule: </strong>Assess milk transfer, not routine early food/water.", "<strong>Latest protocol: </strong>IAP Nutrition 2026 / WHO 2026", "<strong>What to do in the exam: </strong>Age in completed months matters.", "<strong>Trace-back: </strong>Day14 &gt; BF"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 20 — Dilute gruel", "<strong>Tempting wrong choice: </strong>Very watery complementary food is adequate if fed often.", "<strong>Why it looks right: </strong>Large volume looks sufficient.", "<strong>Decisive discriminator: </strong>Energy and iron density may be inadequate.", "<strong>Correct rule: </strong>Thick, diverse age-appropriate foods at 6 months.", "<strong>Latest protocol: </strong>IAP Nutrition 2026 / WHO 2023", "<strong>What to do in the exam: </strong>Ask density, not just volume.", "<strong>Trace-back: </strong>Day14 &gt; Complementary Feeding"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 21 — Responsive feeding", "<strong>Tempting wrong choice: </strong>Distract with screens and force each spoon.", "<strong>Why it looks right: </strong>It may increase immediate intake.", "<strong>Decisive discriminator: </strong>Poor responsive feeding can worsen aversion.", "<strong>Correct rule: </strong>Respect hunger/satiety and avoid coercion/screens.", "<strong>Latest protocol: </strong>WHO Complementary Feeding 2023 / IAP 2026", "<strong>What to do in the exam: </strong>Choose relationship-focused feeding.", "<strong>Trace-back: </strong>Day14 &gt; Feeding Behavior"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 22 — SAM edema", "<strong>Tempting wrong choice: </strong>Normal MUAC excludes SAM when bilateral pitting edema is present.", "<strong>Why it looks right: </strong>Anthropometry seems reassuring.", "<strong>Decisive discriminator: </strong>Edema independently defines SAM.", "<strong>Correct rule: </strong>Any one SAM criterion is sufficient.", "<strong>Latest protocol: </strong>IAP SAM 2026 / WHO 2023", "<strong>What to do in the exam: </strong>Check both feet.", "<strong>Trace-back: </strong>Day14 &gt; SAM"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 23 — MAM vs SAM MUAC", "<strong>Tempting wrong choice: </strong>MUAC 11.3 cm is MAM.", "<strong>Why it looks right: </strong>It is near the border.", "<strong>Decisive discriminator: </strong>&lt;11.5 cm = SAM for 6–59 months.", "<strong>Correct rule: </strong>11.5–&lt;12.5 MAM without edema.", "<strong>Latest protocol: </strong>IAP SAM 2026", "<strong>What to do in the exam: </strong>Exact cutoff is decisive.", "<strong>Trace-back: </strong>Day14 &gt; SAM Cutoffs"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 24 — SAM vs stunting", "<strong>Tempting wrong choice: </strong>HAZ &lt;−3 alone means SAM.", "<strong>Why it looks right: </strong>Both use −3 SD.", "<strong>Decisive discriminator: </strong>SAM uses WHZ/MUAC/edema, not HAZ.", "<strong>Correct rule: </strong>Severe stunting is not identical to acute malnutrition.", "<strong>Latest protocol: </strong>IAP SAM 2026 / WHO 2023", "<strong>What to do in the exam: </strong>Name index and denominator.", "<strong>Trace-back: </strong>Day14 &gt; Anthropometry"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 25 — SAM disposition", "<strong>Tempting wrong choice: </strong>Every child with SAM must be admitted.", "<strong>Why it looks right: </strong>SAM is severe.", "<strong>Decisive discriminator: </strong>Appetite and medical complications determine setting.", "<strong>Correct rule: </strong>Complicated/poor appetite → facility; uncomplicated → community.", "<strong>Latest protocol: </strong>IAP SAM 2026 / WHO 2026", "<strong>What to do in the exam: </strong>Triage complications first.", "<strong>Trace-back: </strong>Day14 &gt; SAM Disposition"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 26 — F-100 first", "<strong>Tempting wrong choice: </strong>Give F-100 immediately to a shocked, hypothermic SAM child.", "<strong>Why it looks right: </strong>F-100 supports weight gain.", "<strong>Decisive discriminator: </strong>Unstable metabolism cannot tolerate rehabilitation load.", "<strong>Correct rule: </strong>F-75 stabilization then transition to F-100/RUTF.", "<strong>Latest protocol: </strong>WHO 2023 / WHO 2026", "<strong>What to do in the exam: </strong>Stabilize first.", "<strong>Trace-back: </strong>Day14 &gt; Therapeutic Feeds"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 27 — Rapid fluids in SAM", "<strong>Tempting wrong choice: </strong>Use standard large IV boluses for all dehydrated SAM children.", "<strong>Why it looks right: </strong>Dehydration is dangerous.", "<strong>Decisive discriminator: </strong>Volume overload and misclassification are high risks.", "<strong>Correct rule: </strong>Use SAM-specific careful assessment and rehydration pathway.", "<strong>Latest protocol: </strong>WHO 2023 / WHO 2026", "<strong>What to do in the exam: </strong>Do not import routine bolus rule.", "<strong>Trace-back: </strong>Day14 &gt; Fluids"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 28 — Iron in unstable SAM", "<strong>Tempting wrong choice: </strong>Start high-dose iron during initial septic stabilization.", "<strong>Why it looks right: </strong>Anemia is common.", "<strong>Decisive discriminator: </strong>Iron is often deferred until rehabilitation.", "<strong>Correct rule: </strong>Treat stabilization first; add iron per programme after recovery.", "<strong>Latest protocol: </strong>WHO/IAP SAM 2026", "<strong>What to do in the exam: </strong>Know phase.", "<strong>Trace-back: </strong>Day14 &gt; Iron in SAM"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 29 — Vitamin A prevention vs therapy", "<strong>Tempting wrong choice: </strong>100,000 IU at 9 months is the xerophthalmia treatment for all ages.", "<strong>Why it looks right: </strong>It is a familiar NHM dose.", "<strong>Decisive discriminator: </strong>Preventive and therapeutic indications differ.", "<strong>Correct rule: </strong>NHM prevention 9 mo 100k; later 200k; eye disease uses therapeutic protocol.", "<strong>Latest protocol: </strong>NHM Vitamin A updated Aug 2026", "<strong>What to do in the exam: </strong>Read prevention vs treatment.", "<strong>Trace-back: </strong>Day14 &gt; Vitamin A"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 30 — Zinc age boundary", "<strong>Tempting wrong choice: </strong>Give 20 mg zinc daily to a 4-month-old with diarrhea.", "<strong>Why it looks right: </strong>20 mg is common pediatric dose.", "<strong>Decisive discriminator: </strong>NHM 2–&lt;6 months uses 10 mg.", "<strong>Correct rule: </strong>10 mg 2–&lt;6 months; 20 mg ≥6 months for 14 days.", "<strong>Latest protocol: </strong>NHM STOP Diarrhoea 2025", "<strong>What to do in the exam: </strong>Use exact months.", "<strong>Trace-back: </strong>Day14 &gt; Zinc"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 31 — Iron salt vs elemental", "<strong>Tempting wrong choice: </strong>Prescribe 36 mg ferrous sulfate as 36 mg elemental iron.", "<strong>Why it looks right: </strong>Drug names look interchangeable.", "<strong>Decisive discriminator: </strong>Elemental fraction differs by salt.", "<strong>Correct rule: </strong>Calculate and verify elemental iron content.", "<strong>Latest protocol: </strong>NHM Anemia Mukt Bharat / IAP Nutrition 2026", "<strong>What to do in the exam: </strong>Read label units.", "<strong>Trace-back: </strong>Day14 &gt; Iron"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 32 — Vitamin D vs rickets", "<strong>Tempting wrong choice: </strong>400 IU/day is definitive rickets therapy.", "<strong>Why it looks right: </strong>It is standard prophylaxis.", "<strong>Decisive discriminator: </strong>Treatment requires supervised higher doses + calcium.", "<strong>Correct rule: </strong>Separate maintenance/prophylaxis from treatment.", "<strong>Latest protocol: </strong>WHO Nutritional Rickets Review 2019", "<strong>What to do in the exam: </strong>Identify intent.", "<strong>Trace-back: </strong>Day14 &gt; Vitamin D"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 33 — CMA detects balanced", "<strong>Tempting wrong choice: </strong>A normal CMA excludes a balanced translocation.", "<strong>Why it looks right: </strong>CMA is genome-wide.", "<strong>Decisive discriminator: </strong>Balanced changes preserve copy number.", "<strong>Correct rule: </strong>Use karyotype when balanced rearrangement is suspected.", "<strong>Latest protocol: </strong>IAP Genomics 2026", "<strong>What to do in the exam: </strong>Match variant class.", "<strong>Trace-back: </strong>Day15 &gt; Genetic Tests"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 34 — Sequence vs association", "<strong>Tempting wrong choice: </strong>Pierre Robin is an association and VACTERL a sequence.", "<strong>Why it looks right: </strong>Both contain multiple anomalies.", "<strong>Decisive discriminator: </strong>Sequence has one initiating defect with cascading consequences; association is nonrandom co-occurrence without single established cause.", "<strong>Correct rule: </strong>Pierre Robin = sequence; VACTERL = association.", "<strong>Latest protocol: </strong>IAP Evaluation of Dysmorphic Child 2026", "<strong>What to do in the exam: </strong>Identify whether a causal chain is present.", "<strong>Trace-back: </strong>Day15 &gt; Dysmorphology"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 35 — CMA always before exome", "<strong>Tempting wrong choice: </strong>All GDD must have CMA before ES/GS.", "<strong>Why it looks right: </strong>Older algorithms often used CMA first.", "<strong>Decisive discriminator: </strong>ACMG 2021 permits ES/GS first- or second-tier.", "<strong>Correct rule: </strong>Choose test by phenotype, availability and guidelines.", "<strong>Latest protocol: </strong>ACMG 2021 / IAP 2026", "<strong>What to do in the exam: </strong>Avoid absolute sequencing rule.", "<strong>Trace-back: </strong>Day15 &gt; Genomics"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 36 — VUS as causal", "<strong>Tempting wrong choice: </strong>A VUS justifies irreversible treatment or prenatal termination.", "<strong>Why it looks right: </strong>It appears in the genetic report.", "<strong>Decisive discriminator: </strong>Uncertain significance is not established pathogenicity.", "<strong>Correct rule: </strong>Seek segregation/functional evidence/reanalysis; avoid major irreversible decisions on VUS alone.", "<strong>Latest protocol: </strong>ACMG-AMP variant interpretation / IAP 2026", "<strong>What to do in the exam: </strong>Classify variant before action.", "<strong>Trace-back: </strong>Day15 &gt; Variant Interpretation"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 37 — PWS vs Angelman", "<strong>Tempting wrong choice: </strong>Loss of maternal 15q imprinting always means Prader–Willi.", "<strong>Why it looks right: </strong>Same region is involved.", "<strong>Decisive discriminator: </strong>PWS loses paternal expression; Angelman maternal neuronal UBE3A.", "<strong>Correct rule: </strong>Use methylation/parent-of-origin and phenotype.", "<strong>Latest protocol: </strong>IAP Genetics 2026 / NHS Genomics", "<strong>What to do in the exam: </strong>Map which parent’s expression is missing.", "<strong>Trace-back: </strong>Day15 &gt; Imprinting"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 38 — Methylation negative Angelman", "<strong>Tempting wrong choice: </strong>Normal methylation excludes Angelman.", "<strong>Why it looks right: </strong>Most Angelman mechanisms affect imprinting.", "<strong>Decisive discriminator: </strong>UBE3A sequence variants can preserve methylation.", "<strong>Correct rule: </strong>Consider UBE3A sequencing if phenotype strong.", "<strong>Latest protocol: </strong>NHS Genomics / IAP Genetics 2026", "<strong>What to do in the exam: </strong>Test mechanism, not only methylation.", "<strong>Trace-back: </strong>Day15 &gt; Angelman"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 39 — 22q11 and live vaccines", "<strong>Tempting wrong choice: </strong>All 22q11 children must receive or avoid every live vaccine.", "<strong>Why it looks right: </strong>Immune deficiency is variable.", "<strong>Decisive discriminator: </strong>T-cell number/function varies.", "<strong>Correct rule: </strong>Immune phenotype guides live-vaccine suitability.", "<strong>Latest protocol: </strong>IAP 22q11 Genetics 2026", "<strong>What to do in the exam: </strong>Check immune assessment.", "<strong>Trace-back: </strong>Day15 &gt; DiGeorge"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 40 — Screen positive C3", "<strong>Tempting wrong choice: </strong>C3 elevation proves propionic acidemia.", "<strong>Why it looks right: </strong>C3 is a recognized marker.", "<strong>Decisive discriminator: </strong>MMA, PA and B12-related disorders overlap.", "<strong>Correct rule: </strong>Confirm with urine organic acids, MMA, homocysteine and B12.", "<strong>Latest protocol: </strong>IAP Genetics 2026 / ACMG biochemical follow-up framework", "<strong>What to do in the exam: </strong>Screen ≠ diagnosis.", "<strong>Trace-back: </strong>Day15 &gt; NBS"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 41 — Normal NBS sick neonate", "<strong>Tempting wrong choice: </strong>Normal newborn screen excludes IEM in an encephalopathic neonate.", "<strong>Why it looks right: </strong>Screen sounds comprehensive.", "<strong>Decisive discriminator: </strong>Panels and sensitivity are limited.", "<strong>Correct rule: </strong>Treat symptomatic IEM based on phenotype and urgent labs.", "<strong>Latest protocol: </strong>IAP Genetics / metabolic emergency practice", "<strong>What to do in the exam: </strong>Symptoms override screen.", "<strong>Trace-back: </strong>Day15 &gt; NBS"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 42 — UCD vs organic acidemia", "<strong>Tempting wrong choice: </strong>Hyperammonemia alone always means a urea-cycle defect.", "<strong>Why it looks right: </strong>Ammonia is very high in UCD.", "<strong>Decisive discriminator: </strong>Organic acidemias can cause secondary hyperammonemia with ketotic acidosis.", "<strong>Correct rule: </strong>Interpret acid-base, ketones and anion gap together.", "<strong>Latest protocol: </strong>PCRRT 2020 / metabolic emergency guidance", "<strong>What to do in the exam: </strong>Look at gas and ketones.", "<strong>Trace-back: </strong>Day15 &gt; IEM"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 43 — Delay dialysis to genotype", "<strong>Tempting wrong choice: </strong>Wait for molecular confirmation before dialysis planning at ammonia 600 µmol/L.", "<strong>Why it looks right: </strong>Genotype specifies treatment.", "<strong>Decisive discriminator: </strong>Neurologic toxicity is time-critical.", "<strong>Correct rule: </strong>Anti-catabolic therapy + scavengers + urgent clearance planning in parallel.", "<strong>Latest protocol: </strong>CHOP neonatal pathway / PCRRT 2020", "<strong>What to do in the exam: </strong>Stabilize first, genotype later.", "<strong>Trace-back: </strong>Day15 &gt; Hyperammonemia"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 44 — FAOD with ketones", "<strong>Tempting wrong choice: </strong>Absent urine ketones rules out a serious metabolic disorder.", "<strong>Why it looks right: </strong>Ketones often rise during fasting.", "<strong>Decisive discriminator: </strong>FAOD and hyperinsulinism suppress ketogenesis.", "<strong>Correct rule: </strong>Check glucose, FFA, acylcarnitines and critical sample.", "<strong>Latest protocol: </strong>CHOP Neonatal Hyperammonemia pathway / metabolic biochemistry", "<strong>What to do in the exam: </strong>Hypoketosis is a clue, not reassurance.", "<strong>Trace-back: </strong>Day15 &gt; FAOD"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 45 — Galactosemia feeding", "<strong>Tempting wrong choice: </strong>Continue lactose feeds until GALT enzyme result returns.", "<strong>Why it looks right: </strong>Testing will confirm.", "<strong>Decisive discriminator: </strong>Milk can worsen hepatic/septic crisis.", "<strong>Correct rule: </strong>Stop galactose/lactose immediately if classic galactosemia strongly suspected.", "<strong>Latest protocol: </strong>International Galactosemia Clinical Guideline 2017", "<strong>What to do in the exam: </strong>Act on strong phenotype before final test.", "<strong>Trace-back: </strong>Day15 &gt; Galactosemia"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 46 — MSUD odor only", "<strong>Tempting wrong choice: </strong>No maple-syrup smell excludes MSUD.", "<strong>Why it looks right: </strong>Odor is memorable.", "<strong>Decisive discriminator: </strong>Odor may be absent/late.", "<strong>Correct rule: </strong>Use amino-acid profile/alloisoleucine and clinical crisis.", "<strong>Latest protocol: </strong>GeneReviews MSUD (updated 2020)", "<strong>What to do in the exam: </strong>Biochemistry beats smell.", "<strong>Trace-back: </strong>Day15 &gt; MSUD"], "fill": "F8F8F8"}, {"t": "callout", "label": "", "title": "", "html": ["Trap 47 — Mitochondrial inheritance always maternal", "<strong>Tempting wrong choice: </strong>All Leigh syndrome is maternally inherited.", "<strong>Why it looks right: </strong>Mitochondria suggest mtDNA.", "<strong>Decisive discriminator: </strong>Many Leigh causes are nuclear and AR/X-linked.", "<strong>Correct rule: </strong>Use genotype and pedigree, not syndrome label alone.", "<strong>Latest protocol: </strong>IAP Genomics 2026", "<strong>What to do in the exam: </strong>Separate organelle from inheritance.", "<strong>Trace-back: </strong>Day15 &gt; Mitochondrial"], "fill": ""}, {"t": "callout", "label": "", "title": "", "html": ["Trap 48 — X-linked risk arithmetic", "<strong>Tempting wrong choice: </strong>Carrier mother means 50% of all children affected.", "<strong>Why it looks right: </strong>Half her sons are affected.", "<strong>Decisive discriminator: </strong>Only sons at 50% risk under simplified assumptions.", "<strong>Correct rule: </strong>Overall affected sons 25% if sex ratio 1:1.", "<strong>Latest protocol: </strong>IAP Genetics 2026 (Mendelian counselling)", "<strong>What to do in the exam: </strong>Specify denominator.", "<strong>Trace-back: </strong>Day15 &gt; Pedigree"], "fill": "F8F8F8"}]}]}, {"id": "part-3", "title": "Volatile Facts Deck", "eyebrow": "", "group": "Days 13–15 Revision", "kind": "notes", "sections": [{"title": "A. One-look numbers and cutoffs", "blocks": [{"t": "table", "head": ["<strong>Trigger</strong>", "<strong>Recall</strong>", "<strong>Trace-back</strong>"], "rows": [["Charts", "WHO 0–5; IAP 5–18", "D13 &gt; Charts"], ["Short stature", "&lt;−2 SDS", "D13 &gt; Height"], ["MPH", "Boy +13 cm; girl −13 cm; divide by 2", "D13 &gt; Formula"], ["Height velocity", "Δheight ×12/months", "D13 &gt; Formula"], ["Preterm correction", "PNA − (40−GA); PMA = GA+PNA", "D13 &gt; Ages"], ["ASD", "M-CHAT-R/F 16–30 mo; AAP screens 18/24 mo", "D13 &gt; ASD"], ["SAM", "WHZ &lt;−3 / MUAC &lt;11.5 cm / edema", "D14 &gt; SAM"], ["MAM", "WHZ −3 to &lt;−2 / MUAC 11.5–&lt;12.5; no edema", "D14 &gt; MAM"], ["F-75 / F-100", "0.75 / 1.00 kcal/mL", "D14 &gt; Feeds"], ["BF", "First hour; exclusive 6 mo; continue ≥2 y", "D14 &gt; BF"], ["CF", "Start 6 mo; 2–3 meals 6–8 mo; 3–4 at 9–23 mo", "D14 &gt; CF"], ["Vitamin A", "9 mo 100,000 IU; later 200,000 IU, 9 doses total", "D14 &gt; NHM"], ["Zinc diarrhea", "2–&lt;6 mo 10 mg; ≥6 mo 20 mg ×14 d", "D14 &gt; NHM"], ["Iron IDA", "~3 mg/kg/day elemental common anchor; treatment ≠ AMB", "D14 &gt; Iron"], ["AR risk", "25% affected per pregnancy carrier×carrier", "D15 &gt; Pedigree"], ["Hyperammonemia", "≥500 µmol/L severe in CHOP; urgent clearance planning", "D15 &gt; Emergency"], ["OTC vs CPS1", "High vs low/normal orotic acid", "D15 &gt; UCD / Notebook D10 Q65"]]}]}, {"title": "B. Timing windows / sequences", "blocks": [{"t": "p", "html": "• Growth velocity: standardized serial measurement over about 6–12 months. [D13 &gt; Growth]"}, {"t": "p", "html": "• Correct preterm developmental age in infancy/early childhood per follow-up protocol. [D13 &gt; Ages]"}, {"t": "p", "html": "• IAP toddler ASD screen M-CHAT-R/F 16–30 months; AAP/CDC 18 and 24 months are routine screen visits. [D13 &gt; ASD]"}, {"t": "p", "html": "• Breastfeeding first hour → exclusive 6 months → complementary at 6 months → breastfeeding ≥2 years. [D14 &gt; Feeding]"}, {"t": "p", "html": "• NHM vitamin A at 9 months then 16–18 months and every six months to 5 years (nine total). [D14 &gt; NHM]"}, {"t": "p", "html": "• NHM diarrhea zinc course is 14 days. [D14 &gt; Zinc]"}, {"t": "p", "html": "• Complicated SAM: stabilization → transition → rehabilitation → community follow-up. [D14 &gt; SAM]"}, {"t": "p", "html": "• Hyperammonemia: stabilize and send urgent metabolic labs in parallel; scavenger/dialysis preparation must not wait for genotype. [D15 &gt; IEM]"}, {"t": "p", "html": "• Newborn-screen positive: urgent contact, assess symptoms, confirm biochemically; timing and panel vary locally. [D15 &gt; NBS]"}]}, {"title": "C. Algorithms — ultra-condensed", "blocks": [{"t": "callout", "label": "", "title": "", "html": ["QUICK ALGORITHM — Growth chart", "• 1. Verify age/chart", "• 2. Plot serial values", "• 3. Calculate velocity/MPH", "• 4. Check red flags", "• 5. Investigate or monitor", "TRACE / SOURCE: D13 &gt; Growth"], "fill": "F7F7F7"}, {"t": "callout", "label": "", "title": "", "html": ["QUICK ALGORITHM — Developmental regression", "• 1. Confirm loss", "• 2. Assess hearing/vision and acute illness", "• 3. Neurologic/metabolic evaluation", "• 4. Start early support", "TRACE / SOURCE: D13 &gt; Development"], "fill": "F7F7F7"}, {"t": "callout", "label": "", "title": "", "html": ["QUICK ALGORITHM — Complicated SAM", "• 1. Identify any SAM criterion", "• 2. Check appetite/danger signs", "• 3. Facility stabilize with F-75", "• 4. Transition after stabilization", "• 5. Rehabilitation and relapse prevention", "TRACE / SOURCE: D14 &gt; SAM"], "fill": "F7F7F7"}, {"t": "callout", "label": "", "title": "", "html": ["QUICK ALGORITHM — IEM crisis", "• 1. ABCs and sepsis parallel", "• 2. Prevent catabolism", "• 3. Glucose/gas/ammonia/ketones/acylcarnitines", "• 4. Metabolic consultation", "• 5. Scavengers/clearance if indicated", "• 6. Confirm later", "TRACE / SOURCE: D15 &gt; IEM"], "fill": "F7F7F7"}]}, {"title": "D. First-line vs definitive / close-distractor mini-bank", "blocks": [{"t": "table", "head": ["<strong>Question pair</strong>", "<strong>One-line discriminator</strong>"], "rows": [["Weight-first vs height-first", "Nutrition/systemic vs endocrine/skeletal"], ["FSS vs constitutional delay", "BA ≈ CA vs BA delayed"], ["ASD vs isolated language", "Joint attention/repetitive patterns vs relatively intact reciprocity"], ["Screen vs diagnosis", "M-CHAT and NBS are screens, not definitive tests"], ["SAM vs severe stunting", "WHZ/MUAC/edema vs HAZ"], ["F-75 vs F-100", "Stabilization vs catch-up"], ["Vitamin A prophylaxis vs therapy", "NHM schedule vs urgent xerophthalmia protocol"], ["CMA vs karyotype", "CNV vs balanced/aneuploidy"], ["PWS vs Angelman", "Paternal expression lost vs maternal UBE3A lost"], ["UCD vs organic acidemia", "Resp alkalosis vs ketotic high-AG acidosis"], ["OTC vs CPS1/NAGS", "Urine orotic acid high vs low/normal"], ["FAOD vs hyperinsulinism", "FFA high vs suppressed with low ketones"]]}]}, {"title": "E. Data / pattern-recognition flash deck", "blocks": [{"t": "p", "html": "• Curve: falling weight-for-age before height-for-age → undernutrition or systemic disease. [D13 &gt; Charts]"}, {"t": "p", "html": "• Bone age: normal in familial short stature, often delayed in constitutional delay. [D13 &gt; Short Stature]"}, {"t": "p", "html": "• Developmental trace: true loss of words/skills → regression, urgent evaluation. [D13 &gt; Development]"}, {"t": "p", "html": "• Behavioral pattern: absent pointing + repetitive play → ASD concern despite adequate words. [D13 &gt; ASD]"}, {"t": "p", "html": "• X-ray: rachitic metaphyseal cupping/fraying/splaying → nutritional rickets; subperiosteal hemorrhage → scurvy. [D14 &gt; Vitamins]"}, {"t": "p", "html": "• Edema: bilateral nutritional pitting edema establishes SAM even if MUAC normal. [D14 &gt; SAM]"}, {"t": "p", "html": "• Phenotype: conotruncal CHD + hypocalcemia + palatal anomaly → 22q11.2. [D15 &gt; Syndrome]"}, {"t": "p", "html": "• Phenotype: neonatal hypotonia → later hyperphagia/obesity → PWS. [D15 &gt; Imprinting]"}, {"t": "p", "html": "• Gas: pH 7.51, PCO2 25, ammonia 520 → suspect UCD and treat hyperammonemia. [D15 &gt; IEM]"}, {"t": "p", "html": "• Gas: pH 7.13, HCO3 9, AG 27, ketones +++, C3 high → organic acidemia PA/MMA. [D15 &gt; IEM]"}, {"t": "p", "html": "• Acylcarnitine C8 high + hypoketotic fasting hypoglycemia → MCAD. [D15 &gt; FAOD]"}, {"t": "p", "html": "• Urine orotic acid high with low citrulline → OTC. [D15 &gt; UCD / Notebook D10 Q65]"}]}, {"title": "F. Calculation formula box (worked + independently checked)", "blocks": [{"t": "table", "head": ["<strong>Formula</strong>", "<strong>Substitution</strong>", "<strong>Result / common trap</strong>"], "rows": [["MPH boy = (father+mother+13)/2", "(174+160+13)/2", "173.5 cm; do not omit +13"], ["Height velocity = Δheight×12/months", "(112−108)×12/8", "6 cm/year; use cm and months"], ["BMI = kg / m²", "20/(1.10×1.10)", "16.53 kg/m²; interpret by age/sex"], ["Corrected age = PNA−(40−GA)", "16−(40−27)", "3 weeks; PMA = 43 weeks"], ["Elemental iron = mg/kg/day × kg", "3×12", "36 mg/day elemental; salt ≠ elemental"], ["F-75 energy math = volume×0.75", "800 mL×0.75", "600 kcal; NOT a SAM starting prescription"], ["Carrier×carrier AR risk", "0.25×100", "25% affected per pregnancy"], ["Anion gap = Na − (Cl + HCO3)", "140−(103+10)", "27 mEq/L; check lab reference and albumin"]]}]}, {"title": "G. Personalized RED / AMBER / GREEN maintenance", "blocks": [{"t": "callout", "label": "", "title": "", "html": ["RED — NO DOCUMENTED SYSTEM-SPECIFIC PERSONAL ERRORS", "• No Day 13–15 wrong/guessed/uncertain or Active Recall failure is recorded in the retrieved persistent notebook. Do not fabricate RED tags.", "• All system-wide factual traps remain in Part 2 for preventive revision; they are not falsely attributed to personal mistakes.", "TRACE / SOURCE: Actual notebook snapshot 13 Oct 2026"], "fill": "E4E4E4"}, {"t": "callout", "label": "", "title": "", "html": ["AMBER / IMPROVING — TRUE CROSS-DAY IEM OVERLAPS", "• ERR-D10-Q65: OTC vs CPS1/NAGS, low citrulline + high urinary orotic acid = OTC. Original 1× knowledge error; R1 PASSED 12 Oct (Day 12 Q114); R2 around 19 Oct, R3 around 2 Nov conditional. Keep Improving, not Mastered.", "• ERR-D10-Q50: suppressed BOHB/FFA and glucagon rise support hyperinsulinism; FAOD generally has high FFA. Original 1×; R1 PASSED 12 Oct (Day 12 Q90). Included only as Day 15 IEM differential overlap; not relabelled as a Day 15 mistake.", "TRACE / SOURCE: NEET_SS_Error_Notebook.md &gt; ERR-D10-Q65 / ERR-D10-Q50"], "fill": "F2F2F2"}, {"t": "callout", "label": "", "title": "", "html": ["GREEN MAINTENANCE — SYSTEM FACTS WITHOUT PERSONAL ERROR STATUS", "• Growth chart choice and velocity; short stature pattern recognition.", "• Developmental regression, ASD screening versus diagnosis.", "• SAM classification/disposition, feeding phases, vitamin A/zinc preventive rules.", "• Chromosomal syndrome signatures, genomic-test selection, newborn screening limits.", "TRACE / SOURCE: System-wide learning objectives Days 13–15"], "fill": "FAFAFA"}]}, {"title": "H. Final 5-minute checklist", "blocks": [{"t": "p", "html": "□ WHO/IAP charts, height velocity, MPH, weight-first vs height-first."}, {"t": "p", "html": "□ Developmental milestones, regression, corrected age, ASD/ADHD/SLD."}, {"t": "p", "html": "□ Breastfeeding/CF ages, responsive feeding."}, {"t": "p", "html": "□ SAM vs MAM, edema, F-75/F-100, complicated SAM."}, {"t": "p", "html": "□ Vitamin A India 9 doses, zinc 14 days, iron elemental."}, {"t": "p", "html": "□ CMA/karyotype/exome/methylation/repeat expansion."}, {"t": "p", "html": "□ Down/Turner/XXY/22q11/Williams/PWS/Angelman."}, {"t": "p", "html": "□ UCD vs organic acidemia vs FAOD, ammonia escalation."}, {"t": "p", "html": "□ OTC vs CPS1/NAGS, C3 PA vs MMA, NBS screening ≠ diagnosis."}, {"t": "p", "html": "□ Notebook AMBER OTC concept retained for R2/R3."}]}, {"title": "I. Truthful source and guideline register (checked 13 October 2026)", "blocks": [{"t": "p", "html": "<strong>IAP Growth Charts 2026 — </strong>Verified direct PDF. https://iapindia.org/pdf/action-plan-2026/Growth-Development-and-Behaviour/001-Understanding-Growth-Charts.pdf"}, {"t": "p", "html": "<strong>IAP Short Stature 2026 — </strong>Verified direct PDF. https://iapindia.org/pdf/action-plan-2026/Growth-Development-and-Behaviour/003-Short-Stature.pdf"}, {"t": "p", "html": "<strong>IAP Milestones 2026 — </strong>Verified direct PDF. https://iapindia.org/pdf/action-plan-2026/Growth-Development-and-Behaviour/004-Physical-Developmental-Milestones.pdf"}, {"t": "p", "html": "<strong>IAP Autism Recognition 2026 — </strong>Verified direct PDF. https://iapindia.org/pdf/action-plan-2026/Neurodevelopment/006-Autism-Recognition-Clinical-Clues-and-Early-Diagnosis.pdf"}, {"t": "p", "html": "<strong>IAP Nutrition 2026 — </strong>Verified direct PDF. https://iapindia.org/pdf/action-plan-2026/Nutrition/006-Infant-Nutrition-Exclusive-Breastfeeding-Complementary-Feeding-Growth-Monitoring.pdf"}, {"t": "p", "html": "<strong>IAP SAM/MAM 2026 — </strong>Verified direct PDF. https://iapindia.org/pdf/action-plan-2026/Nutrition/008-Malnutrition-MAM-Moderate-Acute-Malnutrition-and-SAM-Severe-Acute-Malnutrition.pdf"}, {"t": "p", "html": "<strong>IAP Dysmorphology 2026 — </strong>Verified direct PDF. https://iapindia.org/pdf/action-plan-2026/Genetics/002-Evaluation-of-a-Dysmorphic-Child.pdf"}, {"t": "p", "html": "<strong>IAP Genomics 2026 — </strong>Verified direct PDF. https://iapindia.org/pdf/action-plan-2026/Genetics/005-Advanced-Genomic-Testing-in-Pediatrics-V2.pdf"}, {"t": "p", "html": "<strong>WHO Complementary Feeding 2023 — </strong>Verified official page. https://www.who.int/publications/i/item/9789240081864"}, {"t": "p", "html": "<strong>WHO Wasting Guideline 2023 — </strong>Verified official page. https://www.who.int/publications/i/item/9789240082830"}, {"t": "p", "html": "<strong>WHO Wasting Implementation 17 Sep 2026 — </strong>Verified official page. https://www.who.int/publications/i/item/9789240122840"}, {"t": "p", "html": "<strong>NHM Vitamin A updated 7 Aug 2026 — </strong>Verified official page. https://nhm.gov.in/index1.php?lang=1&amp;level=3&amp;sublinkid=1452&amp;lid=801"}, {"t": "p", "html": "<strong>NHM STOP Diarrhoea 2025 — </strong>Verified official PDF. https://nhm.gov.in/New_Updates_2018/NHM_Components/RMNCHA/CH/Schemes/IDCF/IDCF-2025/Guidance_Document_on-STOP_Diarrhoea_Campaign_2025.pdf"}, {"t": "p", "html": "<strong>NHM Anemia Mukt Bharat — </strong>Verified official PDF. https://nhm.gov.in/images/pdf/Nutrition/AMB-guidelines/Anemia-Mukt-Bharat-Operational-Guidelines-FINAL.pdf"}, {"t": "p", "html": "<strong>ACMG exome/genome 2021 — </strong>Verified published guideline. https://www.nature.com/articles/s41436-021-01242-6"}, {"t": "p", "html": "<strong>CHOP Neonatal Hyperammonemia — </strong>Verified official institutional pathway. https://www.chop.edu/clinical-pathway/neonatal-hyperammonemia-clinical-pathway"}, {"t": "p", "html": "<strong>PCRRT Hyperammonemia 2020 — </strong>Verified peer-reviewed consensus. https://www.nature.com/articles/s41581-020-0267-8"}, {"t": "p", "html": "<strong>NHS Genomic Imprinting — </strong>Verified official educational page. https://www.genomicseducation.hee.nhs.uk/genotes/knowledge-hub/genomic-imprinting/"}, {"t": "p", "html": "<strong>CDC ASD screening 2026 — </strong>Verified official page. https://www.cdc.gov/autism/diagnosis/"}, {"t": "p", "html": "<strong>Nelson Pediatrics 22e — </strong>Conceptual reference; no full-text direct access claimed. Textbook: Nelson Textbook of Pediatrics, 22nd ed."}, {"t": "p", "html": "<strong>OP Ghai Essential Pediatrics — </strong>Complementary Indian textbook; no full-text direct access claimed. Textbook: Ghai Essential Pediatrics (edition/page not asserted)"}, {"t": "p", "html": "<strong>Cloherty and Stark Manual of Neonatal Care — </strong>Neonatal specialty background; no full-text direct access claimed. Textbook: Manual of Neonatal Care (edition/page not asserted)"}, {"t": "p", "html": "<strong>Marrow NEET-SS Pediatrics — </strong>Optional; no lawful accessible notes used. Not used; no paid-source access claimed"}, {"t": "p", "html": "<strong>PrepLadder NEET-SS Pediatrics — </strong>Optional; no lawful accessible notes used. Not used; no paid-source access claimed"}]}, {"title": "J. Four-stage QA ledger and six controls (editorial; not external review)", "blocks": [{"t": "table", "head": ["<strong>Stage</strong>", "<strong>Status / actions</strong>", "<strong>Unresolved or limit</strong>"], "rows": [["1. Full-document critique", "Reviewed scope, duplicate concepts, flow, trap specificity and day trace tags; revised overlap labels.", "Day 15 source edition itself flags some original MCQ audit uncertainty; no original keys copied."], ["2. Medical/guideline audit", "Cross-checked IAP 2026, NHM 2025/26, WHO 2023/26, ACMG 2021 and hyperammonemia pathways; named divergent rules.", "Not an independent clinician/pharmacist certification; dose/product local verification remains necessary."], ["3. Examiner/teaching audit", "40+ factual traps, 35 pearls, multiple management algorithms, image/data and formula cues; no answer-key-dependent MCQs.", "MCQ difficulty calibration N/A (no MCQs in this system-end document)."], ["4. Adversarial + layout", "Searched for absolute statements, source mixing, false notebook REDs, unit mistakes and future-topic leakage; rendered and reviewed A4 pages.", "Any remaining local-programme variance is labelled rather than guessed."]]}, {"t": "callout", "label": "", "title": "", "html": ["SIX CONTROL CHECKS", "• 1 | Topic traceability: Day 13–15 map and trace-back labels across sections and traps.", "• 2 | Source register: only directly retrieved official/peer-reviewed sources labelled Verified; textbooks/coaching access limitations disclosed.", "• 3 | Calculations: MPH, velocity, BMI, corrected age, iron, F-75 and Mendelian probability recomputed independently.", "• 4 | MCQ difficulty: not applicable because this deliverable contains no MCQ test or answer key.", "• 5 | RED/AMBER/R1–R3: only actual notebook cross-over entries; no invented Day 13–15 errors or mastery.", "• 6 | Regression: post-edit recheck of required headings, 35 pearls, trap labels/count, formulas, source labels and A4 render.", "TRACE / SOURCE: Editorial QA ledger; no external reviewer claim"], "fill": "F6F6F6"}, {"t": "p", "html": "PART II — DAY 16 CARDIOLOGY (NOT SYSTEM-END)"}, {"t": "p", "html": "NEET-SS + ICP Paediatrics — Day 16"}, {"t": "p", "html": "Congenital Heart Disease: Approach • Fetal Circulation • Murmurs • Paediatric ECG • Chest X-ray"}, {"t": "p", "html": "Wednesday 14 October 2026  |  Locked 73-day plan, Day 16  |  75 base MCQs + 5 additional spaced-retest MCQs  |  8 cases  |  6 interpretation stations  |  5 supplementary calculations"}, {"t": "p", "html": "LEARNER NOTE: All questions are original. Answers are separated from the question booklet. Clinical pathways are educational and must be adapted to local protocols and specialist judgement."}]}]}, {"id": "part-4", "title": "Comprehensive Notes", "eyebrow": "Part A", "group": "Study Notes", "kind": "notes", "sections": [{"title": "A1. Fetal circulation: trace the streams", "blocks": [{"t": "p", "html": "Placental oxygenated blood returns through the single umbilical vein. A substantial fraction crosses the ductus venosus into the IVC, while some traverses the hepatic sinusoids. In the right atrium, relatively oxygen-rich IVC flow is preferentially streamed across the foramen ovale to the left atrium → left ventricle → ascending aorta, supporting the brain and myocardium. SVC blood preferentially enters the right ventricle → pulmonary artery; high fetal PVR directs most right-ventricular output across the ductus arteriosus into the descending aorta. Two umbilical arteries return fetal blood to the placenta."}, {"t": "table", "head": ["<strong>Shunt</strong>", "<strong>Connection</strong>", "<strong>Dominant fetal function</strong>", "<strong>After birth</strong>"], "rows": [["Ductus venosus", "Umbilical vein → IVC", "Bypass much hepatic circulation", "Functional closure as umbilical flow ceases"], ["Foramen ovale", "Right atrium → left atrium", "Atrial right-to-left streaming", "LA pressure rises; flap functionally closes"], ["Ductus arteriosus", "Pulmonary artery → descending aorta", "Bypass high-resistance fetal lungs", "Oxygen ↑ and prostaglandins ↓; constricts"], ["Umbilical arteries", "Fetal internal iliac branches → placenta", "Return fetal blood to placenta", "Obliterate after birth"]]}, {"t": "p", "html": "Mechanism chain: first breaths → alveolar expansion and oxygenation → pulmonary arteriolar vasodilation → PVR falls → pulmonary blood flow and LA venous return rise → LA pressure exceeds RA pressure → FO flap closes. Cord clamping removes low-resistance placenta → SVR rises. Higher oxygen tension and loss of placental prostaglandins promote ductal constriction. Transitional right-to-left ductal shunting may persist or recur with high PVR (e.g., PPHN)."}]}, {"title": "A2. Parallel fetal versus serial postnatal circuits", "blocks": [{"t": "table", "head": ["<strong>State</strong>", "<strong>Pulmonary vascular resistance</strong>", "<strong>Systemic vascular resistance</strong>", "<strong>Ductal direction</strong>", "<strong>Consequence</strong>"], "rows": [["Fetus", "High", "Low due to placenta", "PA → aorta", "Parallel bypass of lungs"], ["Normal transition", "Falls sharply", "Rises after cord clamp", "Can transiently become aorta → PA", "Pulmonary flow increases"], ["PPHN", "Remains high or rises", "Variable", "PA → aorta may recur", "Postductal hypoxaemia"], ["Duct-dependent systemic CHD", "Variable", "Systemic output obstructed", "PA → descending aorta supplies body", "Shock as ductus closes"], ["Duct-dependent pulmonary CHD", "Pulmonary outflow obstructed", "Variable", "Aorta → PA supplies lungs", "Cyanosis as ductus closes"]]}, {"t": "p", "html": "Critical interpretation: a 48–72-hour presentation of shock with poor femoral pulses may be a duct-dependent systemic lesion even with no murmur and an earlier normal oxygen screen. Conversely, progressively cyanotic newborns may depend on a patent ductus for pulmonary blood flow. Mixed or parallel circulations require deliberate balancing of systemic and pulmonary flow; indiscriminate hyperoxia/hyperventilation can worsen systemic perfusion in selected lesions."}]}, {"title": "A3. Classify CHD by physiology before naming anatomy", "blocks": [{"t": "table", "head": ["<strong>Presentation</strong>", "<strong>First physiologic group</strong>", "<strong>Examples as recognition clues</strong>", "<strong>First clinical discriminator</strong>"], "rows": [["Acyanotic with increased flow", "Left-to-right shunt", "VSD, PDA, AVSD", "Feeding tachypnoea after PVR fall; pulmonary plethora"], ["Acyanotic with obstruction", "Outflow/arch obstruction", "Coarctation, aortic stenosis", "Weak femorals; arm-leg pressure difference"], ["Cyanotic with low pulmonary flow", "Outflow obstruction/right-to-left shunt", "TOF, pulmonary atresia", "Pulmonary oligemia; cyanosis"], ["Cyanotic with admixture", "Mixed circulations", "TGA, TAPVC, truncus", "Hypoxaemia often out of proportion to lung signs"], ["Hypoxaemia without structural CHD", "Pulmonary vascular or lung disease", "PPHN, pneumonia, RDS, sepsis", "Echo anatomy and shunt direction"]]}, {"t": "p", "html": "The Day 16 task is to recognize physiology and select tests; detailed lesion anatomy, surgical management and arrhythmia treatment are covered on their scheduled later cardiology days."}]}, {"title": "A4. Decision algorithm 1 — Sick neonate: cyanosis or shock", "blocks": [{"t": "list", "ordered": true, "items": ["Recognize central cyanosis, respiratory distress, poor perfusion, metabolic acidosis, feeding collapse or abnormal pulses; initiate ABC stabilization and continuous monitoring.", "Measure RIGHT-HAND preductal and FOOT postductal SpO2, heart rate, respiratory effort, four-limb perfusion/pulses, BP, glucose, temperature, blood gas/lactate; assess sepsis and lung disease concurrently.", "If shock, weak/absent femorals, severe cyanosis or clinical concern for duct dependence: obtain immediate senior NICU/cardiology help and urgent echocardiography; do not wait for CXR/ECG or a murmur.", "For suspected duct-dependent CHD, start IV prostaglandin E1 per local neonatal protocol while preparing for apnea/hypotension and urgent transfer; IAP-NNF 2026 QRG describes 0.05–0.1 microgram/kg/min in the sick-neonate pathway. Titrate with specialist guidance. Once ductal patency is confirmed, many protocols reduce to the lowest effective dose (often about 0.01–0.05 microgram/kg/min) to limit apnea. Do not use PGE1 as a fix for obstructed TAPVC, where pulmonary venous obstruction needs urgent surgery.", "Avoid indiscriminate hyperoxia/hyperventilation in suspected duct-dependent systemic or single-ventricle physiology; titrate oxygen to lesion physiology under specialist care.", "Obtain echo anatomy, ductal flow, pulmonary pressure, ventricular function and systemic perfusion; treat associated sepsis, hypoglycaemia, hypothermia and acid-base disturbances."]}, {"t": "p", "html": "Dose safety: prostaglandin infusion is a high-alert neonatal medication. Institutional dosing, dilution, pump programming, airway readiness and specialist supervision are mandatory; the numerical example later is educational, not a prescription."}]}, {"title": "A5. Decision algorithm 2 — WELL newborn CCHD screen (IAP-NNF 2026)", "blocks": [{"t": "list", "ordered": true, "items": ["At ≥24 hours of life (or before earlier discharge), measure SpO2 on the RIGHT HAND and ONE FOOT in a clinically stable infant off supplemental oxygen.", "Any reading &lt;90% in either site at any time → IMMEDIATE FAIL → clinical evaluation for cardiac/noncardiac hypoxaemia and echocardiography pathway. No rescreen.", "PASS only if BOTH sites are ≥95% AND absolute right-hand/foot difference is ≤3 percentage points.", "Otherwise INDETERMINATE → repeat BOTH sites ONCE after 1 hour; if both ≥95% and difference ≤3% → PASS; otherwise FAIL and evaluate.", "A PASS never overrides cyanosis, abnormal femoral pulses, pathological murmur, shock, antenatal CHD concern or evolving illness. Coarctation is a classic false negative."]}, {"t": "table", "head": ["<strong>Example</strong>", "<strong>Right hand</strong>", "<strong>Foot</strong>", "<strong>2026 result</strong>"], "rows": [["S1", "96%", "96%", "PASS"], ["S2", "97%", "94%", "INDETERMINATE → one 1-hour repeat"], ["S3", "88%", "95%", "IMMEDIATE FAIL"], ["S4", "94%", "94%", "INDETERMINATE → one repeat"], ["S5", "94%", "94% again after repeat", "FAIL"]]}, {"t": "p", "html": "Framework clarification: this is an actually consulted INDIAN IAP-NNF Presidential Action Plan 2026 quick-reference guideline, which explicitly adopts the AAP 2025 simplified algorithm. The older “≥95% in either site” rule and two repeat screens are superseded in this framework."}]}, {"title": "A6. Bedside CHD examination and fetal echo indications", "blocks": [{"t": "table", "head": ["<strong>Bedside item</strong>", "<strong>Abnormal finding</strong>", "<strong>What it suggests</strong>"], "rows": [["Color", "Central cyanosis; severe hypoxaemia", "Cyanotic CHD, PPHN, respiratory illness"], ["Femoral pulses", "Weak, delayed or absent relative to brachial", "Coarctation / interrupted arch"], ["Arm vs leg BP", "Upper-limb systolic ≥20 mmHg higher than leg (screening clue)", "Arch obstruction; echo needed"], ["Precordium", "Heave, thrill, gallop", "Hemodynamic load / pathologic murmur"], ["S2", "Single loud or fixed wide split", "Specific structural physiology; interpret context"], ["Liver/feeding", "Hepatomegaly, sweating, tachypnoea during feeds", "Infant heart failure"], ["Antenatal risk", "Maternal anti-Ro/La, diabetes, abnormal scan, CHD family history", "Targeted fetal echo"]]}, {"t": "p", "html": "Indications for targeted fetal echo from IAP-NNF 2026 include abnormal fetal four-chamber/outflow views, fetal arrhythmia, increased nuchal translucency, nonimmune hydrops, chromosomal/extracardiac anomalies, first-degree family CHD, pregestational diabetes, maternal anti-Ro/La disease and selected teratogen exposures. A normal antenatal scan does not exclude CCHD."}]}, {"title": "A7. Murmurs: timing first, then location and the child", "blocks": [{"t": "table", "head": ["<strong>Feature</strong>", "<strong>Often innocent</strong>", "<strong>Concerning / pathological</strong>"], "rows": [["Timing", "Short systolic", "Diastolic, holosystolic, persistent continuous"], ["Intensity", "Usually 1–2/6", "≥4/6, thrill; grade 3 can be either"], ["Quality", "Musical/vibratory", "Harsh, blowing, high-pitched with other red flags"], ["Position", "Changes/disappears standing", "Persistent despite position"], ["Associated findings", "Normal S2, pulses, growth", "Abnormal S2, cyanosis, poor pulses, failure to thrive"], ["Age", "Older asymptomatic child often innocent", "Newborn murmur deserves greater caution"]]}, {"t": "table", "head": ["<strong>Murmur</strong>", "<strong>Typical auscultation</strong>", "<strong>Mechanism / key discriminator</strong>"], "rows": [["Still murmur", "Vibratory, musical, LLSB/apex, louder supine", "Innocent flow phenomenon"], ["Venous hum", "Continuous infraclavicular/neck; changes with jugular pressure", "Innocent venous return"], ["Pulmonary flow", "Soft ejection at LUSB", "May be innocent; assess S2 and symptoms"], ["VSD", "Harsh holosystolic LLSB", "LV → RV systolic pressure gradient"], ["PDA", "Continuous infraclavicular; bounding pulses", "Aortic runoff into pulmonary artery"], ["ASD", "Pulmonary ejection murmur + fixed split S2", "Increased pulmonary valve flow, not ASD flow itself"], ["Mitral regurgitation", "Apical holosystolic radiating to axilla", "LV → LA systolic regurgitation"], ["Semilunar regurgitation", "Early diastolic decrescendo", "Diastolic regurgitation; pathological"]]}, {"t": "p", "html": "Levine intensity: 1 barely heard; 2 soft but easily heard; 3 loud without thrill; 4 thrill; 5 thrill and audible with edge of stethoscope; 6 audible with stethoscope off chest. Loudness alone neither rules in nor rules out critical CHD. The approach to a murmur is symptom assessment first; routine ECG/CXR for every innocent-sounding murmur is not recommended."}]}, {"title": "A8. Paediatric ECG — a reproducible reading sequence", "blocks": [{"t": "list", "ordered": true, "items": ["Check identity, age, paper speed/calibration and tracing quality.", "Determine rate, rhythm regularity, sinus P-wave axis and P-QRS relation.", "Measure PR, QRS and QT/QTc against AGE-SPECIFIC norms.", "Determine QRS frontal axis (lead I and aVF, then quadrant).", "Evaluate P-wave enlargement, QRS voltages, R/S progression and T-wave polarity against age.", "Integrate with symptoms, examination and echo rather than naming anatomy from ECG alone."]}, {"t": "table", "head": ["<strong>Age / finding</strong>", "<strong>Common interpretation</strong>", "<strong>Important trap</strong>"], "rows": [["Term newborn", "Rightward QRS axis and relative RV dominance", "Do not use adult-axis thresholds"], ["First 2–3 days", "Upright V1 T wave may be normal", "Persistent positive V1 beyond week 1 raises concern"], ["First week", "V1 T wave usually inverts", "Age and gestation affect normal range"], ["Infant with superior axis", "Think AVSD / tricuspid atresia among differentials", "Axis does not define anatomy"], ["Short PR + delta wave", "Ventricular pre-excitation pattern", "Short PR alone is not WPW"], ["Prolonged QTc + syncope", "Possible arrhythmic risk", "Review drugs, electrolytes and family history"]]}, {"t": "p", "html": "Approximate neonatal frontal QRS axis often lies around +60° to +180°, but published age/gestation-specific reference distributions vary. Avoid a single rigid adult cutoff. The Royal Children’s Hospital ECG guidance was consulted for neonatal V1 T-wave evolution and superior-axis associations."}]}, {"title": "A9. Chest X-ray: read the flow before naming the silhouette", "blocks": [{"t": "list", "ordered": true, "items": ["Confirm age, projection (AP vs PA), position, rotation and inspiratory quality.", "Assess cardiothoracic silhouette cautiously in supine AP neonates (magnification and thymus).", "Assess pulmonary vascularity: oligemia, normal markings, plethora, venous congestion/edema.", "Evaluate mediastinal contour, aortic arch, lungs, pleura and skeletal clues.", "Use classic patterns as prompts for echo, never as an exclusion test."]}, {"t": "table", "head": ["<strong>Pattern</strong>", "<strong>Classical association</strong>", "<strong>Limitation / mechanism</strong>"], "rows": [["Egg-on-string", "d-TGA", "Narrow vascular pedicle; not always present early"], ["Boot-shaped heart", "TOF", "RVH and upturned apex; usually reduced pulmonary vascularity"], ["Snowman / figure-of-eight", "Supracardiac TAPVC", "Enlarged venous channels; often not evident in early newborn"], ["Pulmonary plethora + cardiomegaly", "Large L→R shunt", "Flow burden after PVR falls; not lesion-specific"], ["Oligemia", "Reduced pulmonary flow", "Think RV outflow obstruction"], ["Diffuse edema + small heart", "Obstructed TAPVC", "Can mimic neonatal primary lung disease"], ["Inferior rib notching", "Coarctation in older child", "Intercostal collaterals; not expected in neonate"]]}]}, {"title": "A10. Must-know numbers and explicit qualifiers", "blocks": [{"t": "table", "head": ["<strong>Item</strong>", "<strong>Value / rule</strong>", "<strong>Source frame</strong>"], "rows": [["Screen timing", "≥24 h or before early discharge", "IAP-NNF 2026"], ["Screen sites", "RIGHT hand + one foot", "IAP-NNF 2026"], ["Immediate failure", "Any SpO2 &lt;90%", "IAP-NNF 2026"], ["Pass", "Both ≥95%, absolute difference ≤3%", "IAP-NNF 2026"], ["Indeterminate", "One repeat at 1 h; fail if still not pass", "IAP-NNF 2026"], ["Arch obstruction clue", "Arm systolic BP ≥20 mmHg above leg; weak femorals", "IAP-NNF 2026"], ["Sick duct-dependent lesion", "IAP-NNF QRG cites PGE1 0.05–0.1 µg/kg/min; institution-specific titration", "IAP-NNF 2026, high-alert"], ["ECG neonatal axis", "Often rightward; age-specific ranges", "RCH / pediatric ECG references"], ["Levine murmur grade", "Thrill begins at grade 4/6", "Clinical examination"]]}]}, {"title": "A11. Mechanism chains and cross-day integration", "blocks": [{"t": "table", "head": ["<strong>Trigger</strong>", "<strong>Physiology</strong>", "<strong>Bedside clue</strong>", "<strong>Management implication</strong>"], "rows": [["Birth aeration", "PVR ↓, pulmonary flow ↑", "L→R shunts emerge over weeks", "Interpret delayed infant HF"], ["Ductal closure in arch obstruction", "Systemic flow ↓", "Shock, weak femorals, lactate ↑", "Urgent PGE1/echo"], ["Ductal closure in pulmonary atresia", "Pulmonary flow ↓", "Progressive cyanosis", "Urgent PGE1/echo"], ["High PVR in PPHN", "Right-to-left PDA/PFO", "Pre/postductal SpO2 gap", "Echo pulmonary pressure and shunts"], ["Large left-to-right shunt", "Pulmonary overcirculation", "Tachypnoea, hepatomegaly, CXR plethora", "Assess echo hemodynamics"], ["ROP/nutrition/genetics earlier errors", "Prior topics require retention", "Separate fresh-stem questions", "Do not count toward base 75"]]}]}, {"title": "A12. Twenty exam pearls", "blocks": [{"t": "list", "ordered": true, "items": ["Fetal ductus venosus bypasses liver; ductus arteriosus bypasses lungs.", "Placental removal raises SVR; lung aeration lowers PVR.", "FO functional closure depends on LA pressure exceeding RA pressure.", "Right-hand SpO2 is preductal; foot SpO2 is postductal.", "Persistent central cyanosis needs urgent diagnostic assessment, not a routine screen.", "No murmur does not exclude d-TGA or HLHS.", "Coarctation is a classic pulse-ox false negative.", "Weak femorals outweigh a reassuring SpO2 screen.", "2026 IAP-NNF pass means ≥95% in BOTH sites and ≤3% difference.", "Any site &lt;90% is an immediate fail; do not rescreen.", "Indeterminate result gets one 1-hour rescreen, not two.", "Failed screens can detect sepsis and PPHN as well as CHD.", "PGE1 is a high-alert drug; anticipate apnea and hypotension.", "In selected parallel-circulation lesions, excessive oxygen can worsen systemic steal.", "Innocent murmurs are usually soft, short, systolic and posture dependent.", "A diastolic murmur is not a Still murmur.", "Fixed wide S2 splitting points toward atrial-level right-sided volume load.", "Neonatal ECG rightward axis is commonly physiological.", "Upright V1 T in first days may be normal; persistence after first week is concerning.", "CXR pulmonary vascularity is often more useful than a named silhouette."]}]}, {"title": "A13. Fourteen close-distractor traps", "blocks": [{"t": "table", "head": ["<strong>Tempting wrong choice</strong>", "<strong>Decisive correction</strong>"], "rows": [["“Right hand 97, foot 94 is pass”", "No: both sites must be ≥95% and difference ≤3%."], ["“Repeat an 88% saturation after one hour”", "No: any &lt;90% is immediate fail."], ["“A passing screen excludes coarctation”", "No: check femorals and arm–leg BP."], ["“No murmur excludes critical CHD”", "No: severe lesions may be silent."], ["“PGE1 is only for cyanosis”", "No: systemic-flow duct dependence can present as shock."], ["“Hyperoxia is always beneficial in CHD”", "No: parallel physiology can suffer pulmonary overcirculation."], ["“The ASD murmur is blood crossing the atrial hole”", "Usually pulmonary flow murmur from increased right-sided output."], ["“Every continuous murmur is PDA”", "Venous hum is innocent, posture/jugular-pressure dependent."], ["“Grade 2 means harmless”", "Symptoms, pulses and timing matter more than loudness alone."], ["“Newborn rightward ECG axis is RVH”", "It is often normal age-related RV dominance."], ["“Upright V1 T is always abnormal”", "May be normal in the first days of life."], ["“Egg-on-string proves TGA”", "Suggestive only; echo is necessary."], ["“Snowman must appear at birth in TAPVC”", "May emerge later with venous enlargement."], ["“A normal CXR rules out CHD”", "Critical CHD may have subtle or normal early CXR."]]}]}, {"title": "A14. Additional high-yield items (added in this revision)", "blocks": [{"t": "p", "html": "Hyperoxia test: compare PaO₂ in room air with PaO₂ after about 10 minutes of 100% oxygen (right radial, preductal sample). A large rise (often above about 150 mmHg) favours lung disease; a blunted rise means a fixed right-to-left shunt (cyanotic CHD or severe PPHN). It is a screening aid only; echo is definitive."}, {"t": "p", "html": "Congenital complete AV block: maternal anti-Ro/SSA or anti-La/SSB antibodies can cause fetal or neonatal complete heart block (slow regular rate, AV dissociation) in a structurally normal heart. Fetal echo with rhythm assessment is indicated; hydrops and low heart rate need specialist planning."}, {"t": "p", "html": "Physiological murmurs and S2: newborn peripheral pulmonary stenosis murmurs radiate to the axillae and back and resolve by about 6 months. Physiological S2 splitting widens on inspiration and narrows on expiration; fixed splitting suggests ASD, and paradoxical splitting (widest on expiration) suggests LBBB or severe aortic stenosis."}, {"t": "p", "html": "Obstructed TAPVC: cyanosis with diffuse pulmonary edema and a small heart in a neonate. PGE1 does not relieve pulmonary venous obstruction and can worsen edema; urgent echo and surgery are the priority."}]}]}, {"id": "cases", "title": "Clinical Cases", "group": "Practice", "kind": "cases", "sections": [{"title": "Case 1 — Maternal autoantibodies and fetal conduction risk", "blocks": [{"t": "p", "html": "Clinical data: A 29-year-old mother with anti-Ro/SSA positivity is referred at 23 weeks. Fetal heart rate is 72/min, persistently regular, with structurally normal four-chamber view on routine scan."}, {"t": "p", "html": "Decision point: Which fetal cardiac problem should be considered and which test is appropriate?"}, {"t": "p", "html": "Reasoning: Anti-Ro/SSA is associated with immune-mediated fetal AV conduction disease. Urgent targeted fetal echocardiography with rhythm assessment is appropriate; structural normality does not exclude conduction disease."}, {"t": "p", "html": "Trap: a normal four-chamber scan does not exclude fetal AV block."}]}, {"title": "Case 2 — Collapse after ductal closure", "blocks": [{"t": "p", "html": "Clinical data: A term newborn feeds well on day 1. At 58 hours: HR 184/min, RR 66/min, capillary refill 6 s, lactate 8 mmol/L, right-hand SpO2 96%, foot 94%, femoral pulses barely felt, arm BP 72/40 and leg BP 45/29 mmHg."}, {"t": "p", "html": "Decision point: What is the physiological emergency and first stabilization pathway?"}, {"t": "p", "html": "Reasoning: Suspect duct-dependent systemic outflow obstruction such as coarctation/IAA. Stabilize ABCs, evaluate sepsis concurrently, start PGE1 per neonatal protocol and obtain urgent echocardiography/transfer; do not wait for an audible murmur."}, {"t": "p", "html": "Trap: near-normal oxygen saturation does not exclude duct-dependent systemic shock."}]}, {"title": "Case 3 — Pre/postductal difference", "blocks": [{"t": "p", "html": "Clinical data: A 38-week neonate with meconium aspiration has SpO2 right hand 97%, foot 82%, RR 74/min, labile oxygenation and echocardiography showing structurally normal heart but high pulmonary arterial pressure with right-to-left ductal flow."}, {"t": "p", "html": "Decision point: What explains the saturation pattern?"}, {"t": "p", "html": "Reasoning: Persistent high PVR drives pulmonary-artery blood through the PDA into the descending aorta, reducing postductal saturation. Treat respiratory disease/PPHN with expert neonatal support; the differential alone does not prove arch obstruction."}, {"t": "p", "html": "Trap: differential cyanosis can be pulmonary vascular, not only structural."}]}, {"title": "Case 4 — Innocent murmur or disease?", "blocks": [{"t": "p", "html": "Clinical data: A healthy 6-year-old has normal exercise tolerance, SpO2 99%, normal pulses and S2, grade 2/6 musical midsystolic LLSB murmur loudest supine and nearly absent standing. No family sudden death."}, {"t": "p", "html": "Decision point: What is the most likely murmur and what features support it?"}, {"t": "p", "html": "Reasoning: Still murmur: musical/vibratory, systolic, low intensity, position dependent and no abnormal associated signs. Explain and reassess if symptoms emerge; do not reflexively order ECG/CXR for every classic innocent pattern."}, {"t": "p", "html": "Trap: a low-grade murmur alone is not proof of innocence in a symptomatic infant."}]}, {"title": "Case 5 — Delayed pulmonary overcirculation", "blocks": [{"t": "p", "html": "Clinical data: A 7-week infant has RR 62/min at rest, diaphoresis with feeding, weight gain only 8 g/day, liver 3 cm below costal margin, SpO2 98%, a harsh LLSB holosystolic murmur and CXR showing pulmonary plethora."}, {"t": "p", "html": "Decision point: What physiological group is likely and what test is needed?"}, {"t": "p", "html": "Reasoning: A significant left-to-right shunt becomes symptomatic as PVR falls; VSD is a strong possibility. Urgent echo evaluates defect, chamber size, flow and function. Oxygen screening cannot exclude this acyanotic presentation."}, {"t": "p", "html": "Trap: normal saturation does not make feeding-associated tachypnoea benign."}]}, {"title": "Case 6 — Screen branch discrimination", "blocks": [{"t": "p", "html": "Clinical data: A well newborn at 30 h has right hand 96%, foot 93%. Repeat 1 hour later: right hand 96%, foot 94%. There is no murmur and femorals are palpable."}, {"t": "p", "html": "Decision point: Under IAP-NNF 2026, pass or fail?"}, {"t": "p", "html": "Reasoning: Initial result is indeterminate (foot &lt;95%, difference 3 points). After the single 1-hour repeat, foot remains &lt;95%; therefore the screen FAILS. Clinical evaluation and echo pathway are indicated; investigate noncardiac hypoxaemia too."}, {"t": "p", "html": "Trap: the older “one site ≥95%” pass rule is superseded."}]}, {"title": "Case 7 — Neonatal ECG axis", "blocks": [{"t": "p", "html": "Clinical data: A 4-day term neonate with normal pulses and saturations has sinus rhythm 142/min, QRS axis +125°, QRS 55 ms, and T wave becoming negative in V1. No clinical signs of CHD."}, {"t": "p", "html": "Decision point: Which findings are age appropriate?"}, {"t": "p", "html": "Reasoning: Rightward QRS axis and evolving V1 T inversion are expected neonatal patterns. Review age-specific norms and avoid adult ECG labels. Echo is reserved for clinical suspicion, not a single normal-age axis."}, {"t": "p", "html": "Trap: adult “right-axis deviation” labels overcall neonatal RVH."}]}, {"title": "Case 8 — Cyanosis with pulmonary edema", "blocks": [{"t": "p", "html": "Clinical data: A 2-day neonate has SpO2 79% despite oxygen, RR 80/min, crackles and diffuse interstitial edema on CXR with no striking cardiomegaly. The cardiac silhouette does not show a classic egg or snowman shape."}, {"t": "p", "html": "Decision point: Which critical cardiac differential must be considered?"}, {"t": "p", "html": "Reasoning: Obstructed TAPVC causes pulmonary venous hypertension and severe edema with cyanosis; urgent echo is needed. Sepsis/pneumonia remain in parallel differential. Absence of snowman in the neonate does not exclude TAPVC."}, {"t": "p", "html": "Trap: severe pulmonary edema in a cyanotic newborn is not always primary lung disease."}]}]}, {"id": "data", "title": "Data Interpretation", "group": "Practice", "kind": "data", "sections": [{"title": "", "blocks": [{"t": "p", "html": "All data are simulated for examination practice. Work the station first; answers appear after the MCQ explanations."}]}, {"title": "Station 1 — Fetal shunt mapping", "blocks": [{"t": "p", "html": "Figure 1. Simplified fetal circulation; intentionally omits detailed streaming and minor pathways. Work the station table without looking at Section G."}, {"t": "table", "head": ["<strong>Segment</strong>", "<strong>Incoming flow</strong>", "<strong>Question</strong>"], "rows": [["X", "Umbilical vein → vessel → IVC", "Identify vessel and bypassed organ"], ["Y", "Right atrium → opening → left atrium", "Name shunt and dominant direction"], ["Z", "Pulmonary artery → vessel → descending aorta", "Name shunt and why it remains open in fetus"]]}, {"t": "p", "html": "<strong>Interpretation:</strong> X ductus venosus (hepatic bypass); Y foramen ovale (RA→LA); Z ductus arteriosus (PA→descending aorta, high fetal PVR and low oxygen/prostaglandins)."}]}, {"title": "Station 2 — IAP-NNF 2026 pulse-ox classification", "blocks": [{"t": "table", "head": ["<strong>Infant</strong>", "<strong>Right hand</strong>", "<strong>Foot</strong>", "<strong>Repeat (if given)</strong>", "<strong>Task</strong>"], "rows": [["A", "96%", "96%", "—", "Classify"], ["B", "96%", "93%", "96%/94% at 1h", "Classify final outcome"], ["C", "89%", "95%", "—", "Classify immediate action"], ["D", "97%", "95%", "—", "Classify"]]}, {"t": "p", "html": "<strong>Interpretation:</strong> A pass; B fail after one repeat (foot 94%); C immediate fail because right hand &lt;90%; D pass (both ≥95%, difference 2%)."}]}, {"title": "Station 3 — Murmur discriminator", "blocks": [{"t": "table", "head": ["<strong>Patient</strong>", "<strong>Timing</strong>", "<strong>Site / quality</strong>", "<strong>Other</strong>", "<strong>Task</strong>"], "rows": [["M1", "Midsystolic", "LLSB musical, softer standing", "Healthy 5-year-old", "Name murmur"], ["M2", "Continuous", "Infraclavicular", "Bounding pulses", "Name likely lesion"], ["M3", "Systolic ejection", "LUSB", "Fixed split S2", "Name physiological mechanism"], ["M4", "Early diastolic", "Left sternal border", "No fever", "Pathological or innocent?"]]}, {"t": "p", "html": "<strong>Interpretation:</strong> M1 Still murmur; M2 PDA likely; M3 pulmonary flow murmur from right-sided volume loading (e.g. ASD); M4 diastolic murmur is pathological until assessed."}]}, {"title": "Station 4 — Age-dependent ECG", "blocks": [{"t": "p", "html": "Figure 2. Synthetic age-dependent lead-V1 comparison, not patient data. Read morphology and use age-specific normal ranges; waveform alone is not diagnostic."}, {"t": "p", "html": "Visual task: compare T polarity in V1, then explain why chronological age changes whether it is expected. Use the simulated trace only as a teaching pattern; determine actual abnormality using age-specific clinical ECG ranges."}, {"t": "table", "head": ["<strong>Trace</strong>", "<strong>Age</strong>", "<strong>QRS axis</strong>", "<strong>T in V1</strong>", "<strong>Task</strong>"], "rows": [["E1", "1 day", "+135°", "Upright", "Normal-age vs abnormal?"], ["E2", "12 days", "+110°", "Upright", "Which concern?"], ["E3", "3 months", "−70°", "Inverted", "Which structural pattern?"], ["E4", "7 years", "+55°", "Inverted", "Broad interpretation?"]]}, {"t": "p", "html": "<strong>Interpretation:</strong> E1 often normal neonatal rightward axis/upright V1 T; E2 persistent upright V1 T beyond week 1 suggests RV strain; E3 superior/leftward axis raises AVSD/tricuspid atresia; E4 normal axis and inverted V1 T can be age appropriate."}]}, {"title": "Station 5 — CXR flow and silhouette", "blocks": [{"t": "p", "html": "Figure 3. Schematic silhouette and vascularity cues only; not actual radiographs. Appearance varies with projection, age and lesion severity."}, {"t": "p", "html": "Visual task: name the first pattern to check (pulmonary vascularity versus congestion), identify which drawing depicts which physiology, then state why the silhouette alone cannot establish the definitive lesion."}, {"t": "table", "head": ["<strong>Film</strong>", "<strong>Cardiac silhouette</strong>", "<strong>Pulmonary markings</strong>", "<strong>Task</strong>"], "rows": [["R1", "Boot shaped", "Reduced", "Name classical physiology"], ["R2", "Egg-shaped narrow pedicle", "Variable", "Name classical lesion"], ["R3", "Normal/small", "Diffuse venous edema", "Name urgent CHD differential"], ["R4", "Enlarged", "Increased vascularity", "Name hemodynamic group"]]}, {"t": "p", "html": "<strong>Interpretation:</strong> R1 TOF-type RVOT obstruction/oligemia; R2 d-TGA classical narrow pedicle; R3 obstructed TAPVC; R4 pulmonary overcirculation from significant left-to-right shunt."}]}, {"title": "Station 6 — Echo triage under conflicting tests", "blocks": [{"t": "table", "head": ["<strong>Infant</strong>", "<strong>Pulse-ox</strong>", "<strong>Bedside examination</strong>", "<strong>CXR/ECG</strong>", "<strong>Task</strong>"], "rows": [["T1", "Pass", "Weak femorals, arm&gt;leg BP", "Nonspecific", "Need echo?"], ["T2", "Pass", "Healthy, musical murmur disappears standing", "No studies", "Need routine urgent echo?"], ["T3", "Fail", "Central cyanosis, no murmur", "Normal early CXR", "Need echo?"], ["T4", "Indeterminate once", "Clinically well", "Normal ECG", "Repeat or discharge?"]]}, {"t": "p", "html": "<strong>Interpretation:</strong> T1 urgent echo despite screen pass; T2 classic innocent pattern without red flags may be followed clinically; T3 urgent echo and stabilization; T4 repeat both sites once after 1 hour, assess clinically."}]}]}, {"id": "revision", "title": "Rapid Revision", "group": "Practice", "kind": "revision", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["Rapid-review cue (answers visible)", "Quick-reference answer — not a blinded recall test"], "rows": [["3 fetal bypasses", "Ductus venosus (liver), foramen ovale (atrial), ductus arteriosus (lungs)"], ["Birth PVR / SVR", "PVR falls; SVR rises"], ["Right-hand vs foot", "Preductal vs postductal"], ["IAP-NNF 2026 PASS", "Both ≥95% and difference ≤3%"], ["IAP-NNF 2026 immediate FAIL", "Any site &lt;90%"], ["Indeterminate", "One 1-hour repeat, then fail if not pass"], ["Pulse-ox false-negative lesion", "Coarctation/IAA can pass early"], ["Danger signs", "Central cyanosis, shock, weak femorals, abnormal S2, hepatomegaly"], ["Innocent murmur", "Short soft systolic musical/positional with normal child"], ["ECG neonatal pattern", "Rightward axis; V1 T changes during first week"], ["CXR first question", "Pulmonary vascularity: oligemia, plethora, venous edema"], ["Echo", "Anatomic confirmation; do not delay in sick neonate"]]}]}]}, {"id": "quizzes", "title": "Quizzes", "group": "Practice", "kind": "quizzes", "sections": []}, {"id": "recall", "title": "Active Recall", "group": "Revise", "kind": "recall", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": true, "items": ["Trace oxygenated placental blood to the fetal ascending aorta.<br>Answer: Placenta → umbilical vein → ductus venosus/IVC → RA → foramen ovale → LA → LV → ascending aorta.", "Name the three fetal bypass pathways and organs/circuits bypassed.<br>Answer: Ductus venosus—hepatic sinusoids; FO—right heart/lung circuit; ductus arteriosus—pulmonary capillaries.", "What happens to PVR and SVR at birth?<br>Answer: PVR falls with lung aeration; SVR rises after placental removal.", "Why does the FO functionally close?<br>Answer: Pulmonary venous return raises LA pressure above RA pressure.", "Why does the ductus constrict?<br>Answer: Oxygen tension rises and prostaglandin support falls.", "What suggests duct-dependent systemic rather than pulmonary flow?<br>Answer: Shock, weak femorals, low systemic perfusion after ductal closure versus predominant progressive cyanosis.", "Which sites are used for CCHD screening?<br>Answer: Right hand and either foot.", "State the current IAP-NNF 2026 pass criteria.<br>Answer: SpO2 ≥95% at BOTH sites and difference ≤3 percentage points.", "State the immediate-fail rule.<br>Answer: Any SpO2 &lt;90% at either site.", "How many rescreens for indeterminate results?<br>Answer: Exactly one repeat of both sites after 1 hour.", "Which critical lesion can pass screening despite severe disease?<br>Answer: Coarctation, also interrupted arch; palpate femorals.", "List four bedside red flags despite a normal SpO2.<br>Answer: Weak femorals, shock, pathologic murmur/abnormal S2, hepatomegaly/feeding diaphoresis.", "What is the difference between a Still murmur and venous hum?<br>Answer: Still: musical systolic LLSB; venous hum: continuous neck/infraclavicular and posture/compression dependent.", "Which grade first has a thrill?<br>Answer: Levine grade 4/6.", "Why is ASD usually associated with a pulmonary ejection murmur?<br>Answer: Increased flow across pulmonary valve, not flow through ASD itself.", "What does an early diastolic murmur imply?<br>Answer: Pathologic semilunar valve regurgitation or another structural cause until evaluated.", "What neonatal ECG axis is often normal?<br>Answer: Rightward frontal QRS axis, often around +60° to +180° with age-specific variation.", "When is upright V1 T physiologic and when concerning?<br>Answer: May be normal first 2–3 days; persistent after first week raises RV strain concern.", "Which ECG axis suggests AVSD?<br>Answer: Superior/leftward QRS axis for age.", "Name four CXR flow patterns.<br>Answer: Oligemia, normal pulmonary vascularity, pulmonary plethora, pulmonary venous congestion/edema.", "Name egg-on-string, boot and snowman associations.<br>Answer: d-TGA; TOF; supracardiac TAPVC respectively, each with sensitivity/age limitations.", "Why can obstructed TAPVC look like primary lung disease?<br>Answer: Pulmonary venous obstruction produces diffuse pulmonary edema with severe hypoxaemia.", "What is the main diagnostic test in suspected structural CHD?<br>Answer: Urgent Doppler echocardiography; ECG/CXR are adjuncts.", "What adverse effects must be anticipated with PGE1?<br>Answer: Apnea, hypotension, flushing/fever; prepare airway and monitored infusion.", "How should you interpret a passing CCHD screen with weak femorals?<br>Answer: It does not exclude coarctation; urgent echo is indicated."]}]}]}, {"id": "notebook", "title": "Error Notebook", "group": "Revise", "kind": "notebook", "sections": []}, {"id": "plan", "title": "Revision Plan", "group": "Revise", "kind": "plan", "sections": [{"title": "Section K — Error Notebook Reconciliation", "h1": "Section K — Error Notebook Reconciliation", "blocks": [{"t": "p", "html": "The latest accessible notebook was read for this run. Five fresh-stem retests are additional to the 75 cardiology questions. Day 15 Q30 was reported directly in the conversation but was not present as an ERR-D15 entry in the accessed notebook; it is explicitly identified here without falsely claiming persistent notebook entry."}, {"t": "table", "head": ["<strong>Original concept</strong>", "<strong>Due window / status</strong>", "<strong>Fresh retest in this document</strong>"], "rows": [["Day 11 Q25 — ETROP Type 1 ROP", "14–15 Oct; Active", "Q13"], ["Day 11 Q46 — corrected age", "14–15 Oct; Active", "Q31"], ["Day 11 Q55 — AAP 2018 ROP timing", "14–15 Oct; Active", "Q49"], ["Day 8 Q41 — preterm nutrition targets", "R2 ~14 Oct; Improving", "Q65"], ["Day 15 Q30 — Patau vs Down", "Reported 13 Oct in chat; not in accessed notebook", "Q77"]]}, {"t": "p", "html": "Additional due Active Recall: Day 11 ROP/PVHI/PVL prompts (13 items) are preserved in the notebook. They are not reproduced in full here to avoid replacing Day 16 cardiology content; review those prompts in the error notebook separately. Day 13 Q5 BEARS is due 15–16 October, not pre-emptively counted today."}]}]}, {"id": "references", "title": "References", "group": "More", "kind": "notes", "sections": [{"title": "Section L — Actually Consulted Source / Guideline Register", "h1": "Section L — Actually Consulted Source / Guideline Register", "blocks": [{"t": "table", "head": ["<strong>Access status</strong>", "<strong>Source</strong>", "<strong>Use / limitation</strong>"], "rows": [["Indian priority — verified", "IAP-NNF Presidential Action Plan 2026, Quick Reference Guideline 24: Screening and Diagnosis of Critical Congenital Heart Disease", "Directly read: ≥24 h, both ≥95%, ≤3%, &lt;90% fail, one rescreen, femoral pulses, arch gradient and PGE1 high-alert context."], ["Indian priority — verified", "IAP-NNF Presidential Action Plan 2026, QRG 29: Approach to Congenital Cyanotic Heart Disease in Neonate", "Directly read: cyanotic neonate, echo urgency, PGE1, caution about excessive oxygen in systemic-flow dependence."], ["Indian cardiology — located", "IAP Action Plan 2026 Cardiology: How to Read an ECG?", "Official chapter identified; not every ECG interval was cross-checked line-by-line."], ["International — verified", "AAP Pediatrics (2025), CCHD screening: new algorithm", "Directly read and concordant with 2026 IAP-NNF adoption."], ["International — verified", "Royal Children’s Hospital Melbourne: Basic paediatric ECG interpretation", "Directly read age-specific axis and right-precordial T-wave guidance."], ["International — verified", "Merck Manual Professional: Overview of Congenital Cardiovascular Anomalies", "Directly read fetal circulation, transitional physiology, duct dependence and echo approach."], ["International — verified", "AAFP 2022: Heart Murmurs in Children, Evaluation and Management", "Directly read murmur red flags and limits of routine ECG/CXR."], ["Reference framework — not accessed", "Nelson Textbook of Pediatrics, 22nd ed.", "Primary conceptual reference requested, but full textbook text not available for direct line-by-line verification."], ["Reference framework — not accessed", "OP Ghai Essential Pediatrics", "Indian complementary textbook requested; specific pages not available."], ["Reference framework — not accessed", "Cloherty and Stark’s Manual of Neonatal Care", "NICU specialty reference requested; specific pages not available."], ["Optional coaching — not accessed", "Marrow NEET-SS Paediatrics; PrepLadder NEET-SS Pediatrics paid notes", "No subscription-only notes accessed or reproduced; original MCQs used."]]}, {"t": "p", "html": "Full navigable URLs for actually consulted official/public sources:"}, {"t": "p", "html": "IAP-NNF Presidential Action Plan 2026, Quick Reference Guideline 24: Screening and Diagnosis of Critical Congenital Heart Disease: https://iapindia.org/pdf/action-plan-2026/QRG-024-Screening-and-Diagnosis-of-Critical-Congenital-Heart-Disease.pdf"}, {"t": "p", "html": "IAP-NNF Presidential Action Plan 2026, QRG 29: Approach to Congenital Cyanotic Heart Disease in Neonate: https://iapindia.org/pdf/action-plan-2026/QRG-029-Approach-to-Congenital-Cyanotic-Heart-Disease-in-Neonate.pdf"}, {"t": "p", "html": "IAP Action Plan 2026 Cardiology: How to Read an ECG?: https://iapindia.org/pdf/action-plan-2026/Cardiology/008-How-to-Read-an-ECG.pdf"}, {"t": "p", "html": "AAP Pediatrics (2025), CCHD screening: new algorithm: https://publications.aap.org/pediatrics/article/155/1/e2024069667/200337/Newborn-Screening-for-Critical-Congenital-Heart"}, {"t": "p", "html": "Royal Children’s Hospital Melbourne: Basic paediatric ECG interpretation: https://www.rch.org.au/clinicalguide/guideline_index/Basic_Paediatric_ECG_interpretation/"}, {"t": "p", "html": "Merck Manual Professional: Overview of Congenital Cardiovascular Anomalies: https://www.merckmanuals.com/professional/pediatrics/congenital-cardiovascular-anomalies/overview-of-congenital-cardiovascular-anomalies"}, {"t": "p", "html": "AAFP 2022: Heart Murmurs in Children, Evaluation and Management: https://www.aafp.org/afp/2022/0300/p250"}]}, {"title": "Section M — Limitations and How to Use This Edition", "h1": "Section M — Limitations and How to Use This Edition", "blocks": [{"t": "p", "html": "This is an educational edition. Section L lists the sources the original author consulted (IAP-NNF 2026 QRGs, AAP 2025, RCH, AAFP, Merck); those guideline statements were not re-verified in this revision, and textbook verification (Nelson 22e, OP Ghai, Cloherty and Stark) was not performed."}, {"t": "p", "html": "Drug doses (including PGE1) are illustrative; always follow the local NICU/NNF protocol and specialist advice. Figures are simulated teaching graphics, not patient ECGs or radiographs."}, {"t": "p", "html": "Question difficulty labels reflect design intent and have not been psychometrically calibrated. The questions and key have not had independent specialist review."}]}]}], "quizSets": [{"k": 1, "from": 1, "to": 16, "n": 16}, {"k": 2, "from": 17, "to": 32, "n": 16}, {"k": 3, "from": 33, "to": 48, "n": 16}, {"k": 4, "from": 49, "to": 64, "n": 16}, {"k": 5, "from": 65, "to": 80, "n": 16}], "mcqCount": 80, "calc": {"n": 5, "href": "calc.html"}};
